const e={"es-first-u01.title":"Animaux","es-first-u01.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u01.w.0":"chat","es-first-u01.w.1":"chien","es-first-u01.w.2":"poisson","es-first-u01.w.3":"oiseau","es-first-u01.w.4":"vache","es-first-u01.w.5":"cochon","es-first-u02.title":"À manger","es-first-u02.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u02.w.0":"pomme","es-first-u02.w.1":"banane","es-first-u02.w.2":"lait","es-first-u02.w.3":"pain","es-first-u02.w.4":"œuf","es-first-u02.w.5":"gâteau","es-first-u03.title":"Jouets","es-first-u03.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u03.w.0":"ballon","es-first-u03.w.1":"voiture","es-first-u03.w.2":"nounours","es-first-u03.w.3":"cerf-volant","es-first-u03.w.4":"train","es-first-u03.w.5":"bateau","es-first-u04.title":"Le corps","es-first-u04.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u04.w.0":"œil","es-first-u04.w.1":"oreille","es-first-u04.w.2":"nez","es-first-u04.w.3":"bouche","es-first-u04.w.4":"main","es-first-u04.w.5":"pied","es-first-u05.title":"Couleurs","es-first-u05.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u05.w.0":"rouge","es-first-u05.w.1":"bleu","es-first-u05.w.2":"jaune","es-first-u05.w.3":"vert","es-first-u05.w.4":"noir","es-first-u05.w.5":"blanc","es-first-u06.title":"Famille","es-first-u06.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u06.w.0":"maman","es-first-u06.w.1":"papa","es-first-u06.w.2":"bébé","es-first-u06.w.3":"garçon","es-first-u06.w.4":"fille","es-first-u06.w.5":"mamie","es-first-u07.title":"À la maison","es-first-u07.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u07.w.0":"lit","es-first-u07.w.1":"chaise","es-first-u07.w.2":"porte","es-first-u07.w.3":"tasse","es-first-u07.w.4":"livre","es-first-u07.w.5":"horloge","es-first-u08.title":"Dehors","es-first-u08.tip":"Regardez les images, écoutez et répétez ensemble. Pas besoin de savoir lire.","es-first-u08.w.0":"soleil","es-first-u08.w.1":"lune","es-first-u08.w.2":"étoile","es-first-u08.w.3":"arbre","es-first-u08.w.4":"fleur","es-first-u08.w.5":"pluie"},s={"es-kinder-u01.title":"Les lettres A, B, C","es-kinder-u01.tip":"Répète le nom des lettres espagnoles comme une chanson : A se dit « a », B se dit « bé », C se dit « cé ».","es-kinder-u01.w.0":"arbre","es-kinder-u01.w.1":"abeille","es-kinder-u01.w.2":"eau","es-kinder-u01.w.3":"bébé","es-kinder-u01.w.4":"bateau","es-kinder-u01.w.5":"banane","es-kinder-u01.w.6":"maison","es-kinder-u01.w.7":"voiture","es-kinder-u01.s.0":"A comme árbol (arbre).","es-kinder-u01.s.1":"B comme bebé (bébé).","es-kinder-u01.s.2":"C comme casa (maison).","es-kinder-u02.title":"Les lettres D, E, F","es-kinder-u02.tip":"E se dit « é ». Cherchez ensemble à la maison des objets qui commencent par D, E, F en espagnol.","es-kinder-u02.w.0":"doigt","es-kinder-u02.w.1":"dé","es-kinder-u02.w.2":"dauphin","es-kinder-u02.w.3":"éléphant","es-kinder-u02.w.4":"étoile","es-kinder-u02.w.5":"fleur","es-kinder-u02.w.6":"fraise","es-kinder-u02.w.7":"photo","es-kinder-u02.s.0":"D comme dado (dé).","es-kinder-u02.s.1":"E comme elefante (éléphant).","es-kinder-u02.s.2":"F comme flor (fleur).","es-kinder-u03.title":"Les lettres G, H, I","es-kinder-u03.tip":"En espagnol, le H ne se prononce pas. huevo se dit « ouébo ».","es-kinder-u03.w.0":"chat","es-kinder-u03.w.1":"ballon","es-kinder-u03.w.2":"poule","es-kinder-u03.w.3":"glace","es-kinder-u03.w.4":"œuf","es-kinder-u03.w.5":"feuille","es-kinder-u03.w.6":"île","es-kinder-u03.w.7":"aimant","es-kinder-u03.s.0":"G comme gato (chat).","es-kinder-u03.s.1":"H comme huevo (œuf).","es-kinder-u03.s.2":"I comme isla (île).","es-kinder-u04.title":"Les lettres J, K, L","es-kinder-u04.tip":"Le J est un son qui vient de la gorge, comme un « r » soufflé. jirafa sonne comme « rirafa ».","es-kinder-u04.w.0":"girafe","es-kinder-u04.w.1":"jus","es-kinder-u04.w.2":"savon","es-kinder-u04.w.3":"koala","es-kinder-u04.w.4":"kiwi","es-kinder-u04.w.5":"lune","es-kinder-u04.w.6":"lion","es-kinder-u04.w.7":"livre","es-kinder-u04.s.0":"J comme jirafa (girafe).","es-kinder-u04.s.1":"K comme koala (koala).","es-kinder-u04.s.2":"L comme luna (lune).","es-kinder-u05.title":"Les lettres M, N, Ñ","es-kinder-u05.tip":"Le Ñ existe seulement en espagnol. Il se prononce « gn » comme dans « montagne ». niño se dit « nigno » !","es-kinder-u05.w.0":"main","es-kinder-u05.w.1":"pomme","es-kinder-u05.w.2":"singe","es-kinder-u05.w.3":"nuage","es-kinder-u05.w.4":"nez","es-kinder-u05.w.5":"neige","es-kinder-u05.w.6":"garçon","es-kinder-u05.w.7":"gnou","es-kinder-u05.s.0":"M comme mano (main).","es-kinder-u05.s.1":"N comme nube (nuage).","es-kinder-u05.s.2":"Ñ comme ñu (gnou).","es-kinder-u06.title":"Les lettres O, P, Q","es-kinder-u06.tip":"Le Q est toujours suivi d'un u et fait le son « k ». queso se dit « késo ».","es-kinder-u06.w.0":"ours","es-kinder-u06.w.1":"œil","es-kinder-u06.w.2":"mouton","es-kinder-u06.w.3":"pain","es-kinder-u06.w.4":"canard","es-kinder-u06.w.5":"balle","es-kinder-u06.w.6":"poisson","es-kinder-u06.w.7":"fromage","es-kinder-u06.s.0":"O comme oso (ours).","es-kinder-u06.s.1":"P comme pan (pain).","es-kinder-u06.s.2":"Q comme queso (fromage).","es-kinder-u07.title":"Les lettres R, S, T","es-kinder-u07.tip":"Le R se roule avec la langue : « rrr ». Si c'est difficile, un « r » simple suffit pour commencer.","es-kinder-u07.w.0":"souris","es-kinder-u07.w.1":"grenouille","es-kinder-u07.w.2":"soleil","es-kinder-u07.w.3":"soupe","es-kinder-u07.w.4":"chaise","es-kinder-u07.w.5":"train","es-kinder-u07.w.6":"tomate","es-kinder-u07.w.7":"tortue","es-kinder-u07.s.0":"R comme rana (grenouille).","es-kinder-u07.s.1":"S comme sol (soleil).","es-kinder-u07.s.2":"T comme tren (train).","es-kinder-u08.title":"Les lettres U à Z","es-kinder-u08.tip":"Le V se prononce exactement comme le B. Le Z fait le son « s ». Tu connais maintenant toutes les lettres !","es-kinder-u08.w.0":"raisin","es-kinder-u08.w.1":"un","es-kinder-u08.w.2":"vache","es-kinder-u08.w.3":"verre","es-kinder-u08.w.4":"yoyo","es-kinder-u08.w.5":"yacht","es-kinder-u08.w.6":"chaussure","es-kinder-u08.w.7":"carotte","es-kinder-u08.s.0":"U comme uva (raisin).","es-kinder-u08.s.1":"V comme vaca (vache).","es-kinder-u08.s.2":"Z comme zapato (chaussure)."},u={"es-g12-u01.title":"Dire bonjour","es-g12-u01.tip":"En espagnol, on met aussi un point d'exclamation et un point d'interrogation à l'envers (¡ ¿) au début de la phrase. Rigolo, non ?","es-g12-u01.w.0":"salut","es-g12-u01.w.1":"au revoir","es-g12-u01.w.2":"merci","es-g12-u01.w.3":"s'il te plaît","es-g12-u01.w.4":"oui","es-g12-u01.w.5":"non","es-g12-u01.w.6":"ami","es-g12-u01.w.7":"bonjour (le matin)","es-g12-u01.w.8":"bonne nuit","es-g12-u01.s.0":"Salut, mon ami !","es-g12-u01.s.1":"Bonjour, maman.","es-g12-u01.s.2":"Merci, s'il te plaît.","es-g12-u01.s.3":"Oui, merci.","es-g12-u01.s.4":"Non, merci.","es-g12-u01.s.5":"Bonne nuit, au revoir.","es-g12-u02.title":"Les nombres de 1 à 10","es-g12-u02.tip":"Compte de uno à diez en levant les doigts un par un.","es-g12-u02.w.0":"un","es-g12-u02.w.1":"deux","es-g12-u02.w.2":"trois","es-g12-u02.w.3":"quatre","es-g12-u02.w.4":"cinq","es-g12-u02.w.5":"six","es-g12-u02.w.6":"sept","es-g12-u02.w.7":"huit","es-g12-u02.w.8":"neuf","es-g12-u02.w.9":"dix","es-g12-u02.s.0":"Un, deux, trois.","es-g12-u02.s.1":"J'ai cinq ans.","es-g12-u02.s.2":"Quatre plus quatre font huit.","es-g12-u02.s.3":"J'ai deux mains.","es-g12-u02.s.4":"Dix doigts.","es-g12-u02.s.5":"Six, sept, huit, neuf, dix.","es-g12-u03.title":"Les couleurs","es-g12-u03.tip":"La couleur se met après le mot qu'elle décrit : « manzana roja » (pomme rouge). Après un mot féminin, le -o devient -a.","es-g12-u03.w.0":"rouge","es-g12-u03.w.1":"bleu","es-g12-u03.w.2":"jaune","es-g12-u03.w.3":"vert","es-g12-u03.w.4":"blanc","es-g12-u03.w.5":"noir","es-g12-u03.w.6":"rose","es-g12-u03.w.7":"orange","es-g12-u03.w.8":"violet","es-g12-u03.s.0":"Le soleil est jaune.","es-g12-u03.s.1":"La pomme est rouge.","es-g12-u03.s.2":"La mer est bleue.","es-g12-u03.s.3":"J'aime le vert.","es-g12-u03.s.4":"Mon chat est noir.","es-g12-u03.s.5":"La fleur est rose.","es-g12-u04.title":"La famille","es-g12-u04.tip":"mamá et papá se prononcent en appuyant sur la fin : « mamA », « papA ». L'accent (´) montre où il faut appuyer.","es-g12-u04.w.0":"maman","es-g12-u04.w.1":"papa","es-g12-u04.w.2":"frère","es-g12-u04.w.3":"sœur","es-g12-u04.w.4":"grand-mère","es-g12-u04.w.5":"grand-père","es-g12-u04.w.6":"bébé","es-g12-u04.w.7":"famille","es-g12-u04.w.8":"chien","es-g12-u04.s.0":"C'est ma maman.","es-g12-u04.s.1":"Mon papa est grand.","es-g12-u04.s.2":"J'ai une petite sœur.","es-g12-u04.s.3":"Ma grand-mère est gentille.","es-g12-u04.s.4":"Le bébé dort.","es-g12-u04.s.5":"Ma famille est grande.","es-g12-u05.title":"Les animaux","es-g12-u05.tip":"Devant le nom d'un animal, on met el ou la : el gato, la vaca.","es-g12-u05.w.0":"chat","es-g12-u05.w.1":"oiseau","es-g12-u05.w.2":"poisson","es-g12-u05.w.3":"cheval","es-g12-u05.w.4":"vache","es-g12-u05.w.5":"cochon","es-g12-u05.w.6":"lapin","es-g12-u05.w.7":"ours","es-g12-u05.w.8":"lion","es-g12-u05.s.0":"Le chat est petit.","es-g12-u05.s.1":"Le lion est grand.","es-g12-u05.s.2":"La vache mange de l'herbe.","es-g12-u05.s.3":"L'oiseau chante.","es-g12-u05.s.4":"J'aime les lapins.","es-g12-u05.s.5":"Le cheval court vite.","es-g12-u06.title":"Les fruits","es-g12-u06.tip":"« Me gusta » veut dire « j'aime ». Dis-le avec ton fruit préféré.","es-g12-u06.w.0":"pomme","es-g12-u06.w.1":"banane","es-g12-u06.w.2":"fraise","es-g12-u06.w.3":"raisin","es-g12-u06.w.4":"poire","es-g12-u06.w.5":"pastèque","es-g12-u06.w.6":"citron","es-g12-u06.w.7":"pêche","es-g12-u06.w.8":"cerise","es-g12-u06.s.0":"J'aime les fraises.","es-g12-u06.s.1":"La pastèque est grosse.","es-g12-u06.s.2":"Je veux une pomme.","es-g12-u06.s.3":"Le citron est jaune.","es-g12-u06.s.4":"Le raisin est sucré.","es-g12-u06.s.5":"Une banane, s'il te plaît.","es-g12-u07.title":"La nourriture","es-g12-u07.tip":"como veut dire « je mange », bebo veut dire « je bois ». Essaie de les dire pendant le repas.","es-g12-u07.w.0":"pain","es-g12-u07.w.1":"riz","es-g12-u07.w.2":"lait","es-g12-u07.w.3":"eau","es-g12-u07.w.4":"fromage","es-g12-u07.w.5":"œuf","es-g12-u07.w.6":"soupe","es-g12-u07.w.7":"poulet","es-g12-u07.w.8":"pizza","es-g12-u07.s.0":"Je veux du pain et du fromage.","es-g12-u07.s.1":"Je bois du lait.","es-g12-u07.s.2":"La soupe est chaude.","es-g12-u07.s.3":"Je mange du riz avec du poulet.","es-g12-u07.s.4":"De l'eau, s'il te plaît.","es-g12-u07.s.5":"J'aime la pizza.","es-g12-u08.title":"Le corps","es-g12-u08.tip":"« Me duele » veut dire « j'ai mal à ». Ajoute l'endroit qui fait mal : Me duele la mano.","es-g12-u08.w.0":"tête","es-g12-u08.w.1":"œil","es-g12-u08.w.2":"nez","es-g12-u08.w.3":"bouche","es-g12-u08.w.4":"oreille","es-g12-u08.w.5":"main","es-g12-u08.w.6":"pied","es-g12-u08.w.7":"cheveux","es-g12-u08.w.8":"dent","es-g12-u08.s.0":"J'ai deux yeux.","es-g12-u08.s.1":"Mes cheveux sont noirs.","es-g12-u08.s.2":"Touche ton nez.","es-g12-u08.s.3":"J'ai mal à la tête.","es-g12-u08.s.4":"Je me lave les mains.","es-g12-u08.s.5":"Ouvre la bouche.","es-g12-u09.title":"L'école","es-g12-u09.tip":"« Voy a » veut dire « je vais à ». Voy a la escuela, voy a casa.","es-g12-u09.w.0":"école","es-g12-u09.w.1":"livre","es-g12-u09.w.2":"crayon","es-g12-u09.w.3":"cartable","es-g12-u09.w.4":"bureau","es-g12-u09.w.5":"maître","es-g12-u09.w.6":"papier","es-g12-u09.w.7":"ciseaux","es-g12-u09.w.8":"tableau","es-g12-u09.s.0":"Je vais à l'école.","es-g12-u09.s.1":"J'ai un crayon.","es-g12-u09.s.2":"Le livre est sur le bureau.","es-g12-u09.s.3":"Mon cartable est bleu.","es-g12-u09.s.4":"Le maître est gentil.","es-g12-u09.s.5":"Donne-moi du papier, s'il te plaît.","es-g12-u10.title":"Ma maison","es-g12-u10.tip":"« está en » veut dire « est dans / est sur ». Dis où se trouvent les choses.","es-g12-u10.w.0":"maison","es-g12-u10.w.1":"porte","es-g12-u10.w.2":"fenêtre","es-g12-u10.w.3":"lit","es-g12-u10.w.4":"cuisine","es-g12-u10.w.5":"salle de bain","es-g12-u10.w.6":"canapé","es-g12-u10.w.7":"lampe","es-g12-u10.w.8":"jardin","es-g12-u10.s.0":"Ma maison est petite.","es-g12-u10.s.1":"Ouvre la porte.","es-g12-u10.s.2":"Je dors dans mon lit.","es-g12-u10.s.3":"Maman est dans la cuisine.","es-g12-u10.s.4":"Le chat est sur le canapé.","es-g12-u10.s.5":"Il y a des fleurs dans le jardin.","es-g12-u11.title":"Les vêtements","es-g12-u11.tip":"« Me pongo » veut dire « je mets ». Dis-le le matin en t'habillant.","es-g12-u11.w.0":"t-shirt","es-g12-u11.w.1":"pantalon","es-g12-u11.w.2":"chaussures","es-g12-u11.w.3":"chapeau","es-g12-u11.w.4":"robe","es-g12-u11.w.5":"manteau","es-g12-u11.w.6":"chaussettes","es-g12-u11.w.7":"écharpe","es-g12-u11.w.8":"gants","es-g12-u11.s.0":"Je mets mon t-shirt.","es-g12-u11.s.1":"Mes chaussures sont rouges.","es-g12-u11.s.2":"Il fait froid, mets ton manteau.","es-g12-u11.s.3":"J'aime cette robe.","es-g12-u11.s.4":"Où est mon chapeau ?","es-g12-u11.s.5":"Les chaussettes sont bleues.","es-g12-u12.title":"Le temps qu'il fait","es-g12-u12.tip":"Pour parler du temps, on utilise hace : Hace sol (il y a du soleil), Hace frío (il fait froid), Hace calor (il fait chaud).","es-g12-u12.w.0":"soleil","es-g12-u12.w.1":"pluie","es-g12-u12.w.2":"neige","es-g12-u12.w.3":"vent","es-g12-u12.w.4":"nuage","es-g12-u12.w.5":"chaleur","es-g12-u12.w.6":"froid","es-g12-u12.w.7":"parapluie","es-g12-u12.w.8":"arc-en-ciel","es-g12-u12.s.0":"Il y a du soleil.","es-g12-u12.s.1":"Aujourd'hui, il fait froid.","es-g12-u12.s.2":"Il pleut beaucoup.","es-g12-u12.s.3":"Il y a de la neige sur la montagne.","es-g12-u12.s.4":"Il fait très chaud.","es-g12-u12.s.5":"Regarde l'arc-en-ciel.","es-g12-u13.title":"Les jours et la journée","es-g12-u13.tip":"En espagnol, les jours s'écrivent sans majuscule. mañana veut dire « demain » mais aussi « matin ».","es-g12-u13.w.0":"lundi","es-g12-u13.w.1":"mardi","es-g12-u13.w.2":"samedi","es-g12-u13.w.3":"dimanche","es-g12-u13.w.4":"aujourd'hui","es-g12-u13.w.5":"demain","es-g12-u13.w.6":"nuit","es-g12-u13.w.7":"après-midi","es-g12-u13.w.8":"semaine","es-g12-u13.s.0":"Aujourd'hui, c'est lundi.","es-g12-u13.s.1":"Demain, c'est mardi.","es-g12-u13.s.2":"Le samedi, il n'y a pas d'école.","es-g12-u13.s.3":"Bonjour (l'après-midi).","es-g12-u13.s.4":"La nuit, je dors.","es-g12-u13.s.5":"Le dimanche, je joue avec papa.","es-g12-u14.title":"Les transports","es-g12-u14.tip":"« Voy en » veut dire « je vais en » : voy en tren, voy en coche.","es-g12-u14.w.0":"voiture","es-g12-u14.w.1":"bus","es-g12-u14.w.2":"train","es-g12-u14.w.3":"vélo","es-g12-u14.w.4":"avion","es-g12-u14.w.5":"bateau","es-g12-u14.w.6":"moto","es-g12-u14.w.7":"taxi","es-g12-u14.w.8":"camion","es-g12-u14.s.0":"Je vais en bus.","es-g12-u14.s.1":"Le train est rapide.","es-g12-u14.s.2":"J'ai un vélo rouge.","es-g12-u14.s.3":"L'avion vole haut.","es-g12-u14.s.4":"Le bateau est sur la mer.","es-g12-u14.s.5":"Papa a une voiture.","es-g12-u15.title":"Jouets et jeux","es-g12-u15.tip":"« Vamos a » veut dire « allons… ». Dis à un ami : ¡Vamos al parque!","es-g12-u15.w.0":"balle","es-g12-u15.w.1":"poupée","es-g12-u15.w.2":"nounours","es-g12-u15.w.3":"petite voiture","es-g12-u15.w.4":"puzzle","es-g12-u15.w.5":"cerf-volant","es-g12-u15.w.6":"ballon","es-g12-u15.w.7":"jeu","es-g12-u15.w.8":"aire de jeux","es-g12-u15.s.0":"Je joue avec la balle.","es-g12-u15.s.1":"Ma poupée est jolie.","es-g12-u15.s.2":"Allons à l'aire de jeux.","es-g12-u15.s.3":"Le ballon est rouge.","es-g12-u15.s.4":"J'aime ce jeu.","es-g12-u15.s.5":"Le cerf-volant vole.","es-g12-u16.title":"La nature","es-g12-u16.tip":"« Veo » veut dire « je vois ». Sors dehors et dis ce que tu vois.","es-g12-u16.w.0":"arbre","es-g12-u16.w.1":"fleur","es-g12-u16.w.2":"rivière","es-g12-u16.w.3":"montagne","es-g12-u16.w.4":"mer","es-g12-u16.w.5":"lune","es-g12-u16.w.6":"étoile","es-g12-u16.w.7":"pierre","es-g12-u16.w.8":"herbe","es-g12-u16.s.0":"L'arbre est haut.","es-g12-u16.s.1":"La lune est blanche.","es-g12-u16.s.2":"Je vois une étoile.","es-g12-u16.s.3":"La rivière est longue.","es-g12-u16.s.4":"Il y a des fleurs sur la montagne.","es-g12-u16.s.5":"J'aime la mer.","es-g12-u17.title":"Les émotions","es-g12-u17.tip":"Pour dire comment on se sent, on utilise estoy : Estoy feliz. Pour une fille, ça finit en -a : cansada, enfadada.","es-g12-u17.w.0":"heureux","es-g12-u17.w.1":"triste","es-g12-u17.w.2":"fâché","es-g12-u17.w.3":"fatigué","es-g12-u17.w.4":"effrayé","es-g12-u17.w.5":"content","es-g12-u17.w.6":"ennuyé","es-g12-u17.w.7":"surpris","es-g12-u17.w.8":"malade","es-g12-u17.s.0":"Je suis heureux.","es-g12-u17.s.1":"Tu es triste ?","es-g12-u17.s.2":"Je suis très fatigué.","es-g12-u17.s.3":"Mon frère est fâché.","es-g12-u17.s.4":"Je n'ai pas peur.","es-g12-u17.s.5":"Aujourd'hui, je suis malade.","es-g12-u18.title":"Les actions","es-g12-u18.tip":"Les mots qui finissent en -ar, -er, -ir sont des mots d'action. On peut les mettre tels quels après « Me gusta ».","es-g12-u18.w.0":"courir","es-g12-u18.w.1":"sauter","es-g12-u18.w.2":"manger","es-g12-u18.w.3":"boire","es-g12-u18.w.4":"dormir","es-g12-u18.w.5":"lire","es-g12-u18.w.6":"chanter","es-g12-u18.w.7":"danser","es-g12-u18.w.8":"nager","es-g12-u18.s.0":"J'aime courir.","es-g12-u18.s.1":"Je veux manger.","es-g12-u18.s.2":"Allons nager.","es-g12-u18.s.3":"Elle chante bien.","es-g12-u18.s.4":"Je lis un livre.","es-g12-u18.s.5":"Le chien saute.","es-g12-u19.title":"Mon quartier","es-g12-u19.tip":"« Hay » veut dire « il y a ». En te promenant dans le quartier, dis : Hay una tienda, hay un parque.","es-g12-u19.w.0":"rue","es-g12-u19.w.1":"magasin","es-g12-u19.w.2":"parc","es-g12-u19.w.3":"hôpital","es-g12-u19.w.4":"bibliothèque","es-g12-u19.w.5":"boulangerie","es-g12-u19.w.6":"marché","es-g12-u19.w.7":"église","es-g12-u19.w.8":"feu rouge","es-g12-u19.s.0":"J'habite dans cette rue.","es-g12-u19.s.1":"Je vais au magasin.","es-g12-u19.s.2":"La bibliothèque est tout près.","es-g12-u19.s.3":"J'achète du pain à la boulangerie.","es-g12-u19.s.4":"Le feu est rouge.","es-g12-u19.s.5":"Ici, il y a un parc.","es-g12-u20.title":"La fête d'anniversaire","es-g12-u20.tip":"« ¡Feliz cumpleaños! » veut dire « Joyeux anniversaire ! ». Dis-le à tes amis le jour de leur anniversaire.","es-g12-u20.w.0":"anniversaire","es-g12-u20.w.1":"cadeau","es-g12-u20.w.2":"gâteau","es-g12-u20.w.3":"bougie","es-g12-u20.w.4":"fête","es-g12-u20.w.5":"chanson","es-g12-u20.w.6":"amis","es-g12-u20.w.7":"chapeau de fête","es-g12-u20.w.8":"glace","es-g12-u20.s.0":"Joyeux anniversaire !","es-g12-u20.s.1":"Aujourd'hui, c'est ma fête.","es-g12-u20.s.2":"J'ai un cadeau pour toi.","es-g12-u20.s.3":"Souffle les bougies.","es-g12-u20.s.4":"Nous chantons une chanson.","es-g12-u20.s.5":"Mes amis mangent le gâteau."},a={"es-g34-u01.title":"Je suis… : se présenter","es-g34-u01.tip":"En espagnol, on oublie souvent le sujet. « Soy Lucía » suffit pour dire « je suis Lucía ».","es-g34-u01.w.0":"élève","es-g34-u01.w.1":"maîtresse","es-g34-u01.w.2":"médecin","es-g34-u01.w.3":"cuisinier","es-g34-u01.w.4":"gentil","es-g34-u01.w.5":"grand","es-g34-u01.w.6":"petit","es-g34-u01.w.7":"intelligent","es-g34-u01.w.8":"nom","es-g34-u01.w.9":"pays","es-g34-u01.s.0":"Je suis Lucía.","es-g34-u01.s.1":"Je viens du Pérou.","es-g34-u01.s.2":"Tu es mon ami.","es-g34-u01.s.3":"Il est médecin.","es-g34-u01.s.4":"Elle est très intelligente.","es-g34-u01.s.5":"Nous sommes élèves.","es-g34-u01.s.6":"Ma maîtresse est gentille.","es-g34-u01.s.7":"Comment tu t'appelles ?","es-g34-u01.g.title":"Le verbe ser : soy, eres, es","es-g34-u01.g.x.0":"« Être » se dit ser. Il change selon la personne : yo soy, tú eres, él/ella es.","es-g34-u01.g.x.1":"À plusieurs : nosotros somos, ellos son.","es-g34-u01.g.x.2":"On utilise ser pour dire le nom, le métier, le pays et le caractère. Soy estudiante. Es de México.","es-g34-u01.g.0":"Je suis élève.","es-g34-u01.g.1":"Tu es grand.","es-g34-u01.g.2":"Elle est maîtresse.","es-g34-u01.g.3":"Nous sommes amis.","es-g34-u01.g.4":"Ils viennent d'Espagne.","es-g34-u01.g.5":"Tu es mon ami.","es-g34-u01.g.5.task":"Récris la phrase en commençant par « Tú »","es-g34-u01.g.6":"Elle est intelligente.","es-g34-u01.g.6.task":"Récris la phrase en commençant par « Ella »","es-g34-u01.g.7":"Nous sommes élèves.","es-g34-u01.g.7.task":"Récris la phrase en commençant par « Nosotros »","es-g34-u01.st.title":"Un nouvel ami","es-g34-u01.st.l.0":"Salut ! Je suis Lucía. Comment tu t'appelles ?","es-g34-u01.st.l.1":"Je m'appelle Mateo. Je viens du Mexique.","es-g34-u01.st.l.2":"Moi, je viens du Pérou. Je suis élève.","es-g34-u01.st.l.3":"Moi aussi. Ma maman est médecin.","es-g34-u01.st.l.4":"Super ! Mon papa est cuisinier.","es-g34-u01.st.l.5":"Tu es très gentille, Lucía.","es-g34-u01.st.q.0":"D'où vient Mateo ?","es-g34-u01.st.q.0.o.0":"Du Mexique","es-g34-u01.st.q.0.o.1":"Du Pérou","es-g34-u01.st.q.0.o.2":"D'Espagne","es-g34-u01.st.q.1":"Que fait le papa de Lucía ?","es-g34-u01.st.q.1.o.0":"Médecin","es-g34-u01.st.q.1.o.1":"Cuisinier","es-g34-u01.st.q.1.o.2":"Professeur","es-g34-u02.title":"Où es-tu ? Comment ça va ?","es-g34-u02.tip":"Pour les sentiments, c'est estar ! Estoy feliz, estoy cansado. Une fille dit contenta, nerviosa, avec un -a à la fin.","es-g34-u02.w.0":"ici","es-g34-u02.w.1":"là-bas","es-g34-u02.w.2":"près","es-g34-u02.w.3":"loin","es-g34-u02.w.4":"content","es-g34-u02.w.5":"nerveux","es-g34-u02.w.6":"occupé","es-g34-u02.w.7":"prêt","es-g34-u02.w.8":"dessus","es-g34-u02.w.9":"dessous","es-g34-u02.s.0":"Je suis à la maison.","es-g34-u02.s.1":"Où es-tu ?","es-g34-u02.s.2":"Le livre est sur le bureau.","es-g34-u02.s.3":"Maman est occupée.","es-g34-u02.s.4":"Nous sommes très contents.","es-g34-u02.s.5":"L'école est tout près.","es-g34-u02.s.6":"Je suis un peu nerveux.","es-g34-u02.s.7":"Tu es prêt ?","es-g34-u02.g.title":"Le verbe estar : le lieu et l'humeur","es-g34-u02.g.x.0":"Pour dire où on est et comment on se sent en ce moment, on utilise estar : estoy, estás, está, estamos, están.","es-g34-u02.g.x.1":"Estoy en casa. (Je suis à la maison) / Está contento. (Il est content)","es-g34-u02.g.x.2":"Ser, c'est « comment on est pour de bon » ; estar, c'est « l'état ou le lieu en ce moment ».","es-g34-u02.g.0":"Je suis à l'école.","es-g34-u02.g.1":"Tu es content ?","es-g34-u02.g.2":"Le chat est sous la chaise.","es-g34-u02.g.3":"Nous sommes prêts.","es-g34-u02.g.4":"Ils sont loin.","es-g34-u02.g.5":"Elle est nerveuse.","es-g34-u02.g.5.task":"Récris la phrase en commençant par « Ella »","es-g34-u02.g.6":"Où es-tu ?","es-g34-u02.g.6.task":"Transforme en question avec « ¿Dónde…? »","es-g34-u02.g.7":"Nous sommes à la maison.","es-g34-u02.g.7.task":"Récris la phrase en commençant par « Nosotros »","es-g34-u03.title":"El et la : le genre des mots","es-g34-u03.tip":"Quand tu apprends un mot nouveau, apprends toujours el ou la avec. Pas « mesa », mais « la mesa » !","es-g34-u03.w.0":"petit garçon","es-g34-u03.w.1":"petite fille","es-g34-u03.w.2":"garçon","es-g34-u03.w.3":"fille","es-g34-u03.w.4":"cahier","es-g34-u03.w.5":"fenêtre","es-g34-u03.w.6":"village","es-g34-u03.w.7":"ville","es-g34-u03.w.8":"main","es-g34-u03.w.9":"problème","es-g34-u03.s.0":"Le petit garçon a un cahier.","es-g34-u03.s.1":"La petite fille ouvre la fenêtre.","es-g34-u03.s.2":"Les garçons jouent au foot.","es-g34-u03.s.3":"Les filles chantent.","es-g34-u03.s.4":"La ville est très grande.","es-g34-u03.s.5":"Le village est petit et joli.","es-g34-u03.s.6":"La main a cinq doigts.","es-g34-u03.s.7":"Ce problème est difficile.","es-g34-u03.g.title":"Les articles el / la / los / las","es-g34-u03.g.x.0":"En espagnol, les noms sont masculins ou féminins. En général, un mot en -o est masculin (el niño) et un mot en -a est féminin (la niña).","es-g34-u03.g.x.1":"Au pluriel, on dit los, las : los niños, las niñas.","es-g34-u03.g.x.2":"Il y a des exceptions : la mano (féminin), el problema (masculin). Apprends le mot avec son article.","es-g34-u03.g.0":"Le petit garçon mange du pain.","es-g34-u03.g.1":"La petite fille a un chat.","es-g34-u03.g.2":"Les garçons sont au parc.","es-g34-u03.g.3":"Les fenêtres sont ouvertes.","es-g34-u03.g.3.task":"Mets au pluriel","es-g34-u03.g.4":"La main est petite.","es-g34-u03.g.5":"Ce problème est facile.","es-g34-u03.g.6":"Les enfants jouent.","es-g34-u03.g.6.task":"Mets au pluriel","es-g34-u03.g.7":"Les filles chantent.","es-g34-u03.g.7.task":"Mets au pluriel","es-g34-u03.st.title":"En classe","es-g34-u03.st.l.0":"Bonjour, les enfants. Ouvrez vos cahiers.","es-g34-u03.st.l.1":"Maîtresse, je n'ai pas mon cahier.","es-g34-u03.st.l.2":"Où est ton cahier, Diego ?","es-g34-u03.st.l.3":"À la maison, sur la table.","es-g34-u03.st.l.4":"J'ai deux cahiers. Prends-en un.","es-g34-u03.st.l.5":"Merci, Ana ! Tu es très gentille.","es-g34-u03.st.q.0":"Où est le cahier de Diego ?","es-g34-u03.st.q.0.o.0":"À l'école","es-g34-u03.st.q.0.o.1":"Sur la table, à la maison","es-g34-u03.st.q.0.o.2":"Dans son sac","es-g34-u03.st.q.1":"Qui prête un cahier ?","es-g34-u03.st.q.1.o.0":"La maîtresse","es-g34-u03.st.q.1.o.1":"Diego","es-g34-u03.st.q.1.o.2":"Ana","es-g34-u04.title":"Pomme rouge, pommes rouges : les adjectifs","es-g34-u04.tip":"Si le nom finit en -a, l'adjectif aussi ; si le nom est au pluriel, l'adjectif prend un -s. Pense à des paires qui vont ensemble.","es-g34-u04.w.0":"grand","es-g34-u04.w.1":"petit","es-g34-u04.w.2":"joli","es-g34-u04.w.3":"laid","es-g34-u04.w.4":"nouveau","es-g34-u04.w.5":"vieux","es-g34-u04.w.6":"rapide","es-g34-u04.w.7":"lent","es-g34-u04.w.8":"propre","es-g34-u04.w.9":"sale","es-g34-u04.s.0":"La pomme est rouge.","es-g34-u04.s.1":"Les pommes sont rouges.","es-g34-u04.s.2":"La nouvelle voiture est rapide.","es-g34-u04.s.3":"Ma maison est petite et jolie.","es-g34-u04.s.4":"Les vieux livres sont sales.","es-g34-u04.s.5":"La tortue est lente.","es-g34-u04.s.6":"Mes chaussures sont propres.","es-g34-u04.s.7":"Le gros chien est laid.","es-g34-u04.g.title":"L'accord des adjectifs : -o/-a, -os/-as","es-g34-u04.g.x.0":"L'adjectif change pour aller avec le nom : el niño alto, la niña alta.","es-g34-u04.g.x.1":"Au pluriel, on ajoute -s : los niños altos, las niñas altas.","es-g34-u04.g.x.2":"Les adjectifs en -e, comme grande ou inteligente, sont pareils au masculin et au féminin : el niño grande, la niña grande.","es-g34-u04.g.x.3":"L'adjectif se met souvent après le nom : la casa bonita.","es-g34-u04.g.0":"La maison est jolie.","es-g34-u04.g.1":"La voiture est neuve.","es-g34-u04.g.2":"Les chiens sont rapides.","es-g34-u04.g.3":"Les filles sont intelligentes.","es-g34-u04.g.4":"La tortue est lente.","es-g34-u04.g.5":"Les pommes sont rouges.","es-g34-u04.g.5.task":"Mets au pluriel","es-g34-u04.g.6":"Le sac à dos est neuf.","es-g34-u04.g.6.task":"Récris la phrase avec « La mochila »","es-g34-u04.g.7":"Les chats sont petits.","es-g34-u04.g.7.task":"Mets au pluriel","es-g34-u05.title":"Les verbes en -ar : hablo, hablas, habla","es-g34-u05.tip":"-o (je), -as (tu), -a (il/elle), -amos (nous), -an (ils). Rien qu'avec la fin du mot, tu sais qui fait l'action !","es-g34-u05.w.0":"parler","es-g34-u05.w.1":"étudier","es-g34-u05.w.2":"écouter","es-g34-u05.w.3":"marcher","es-g34-u05.w.4":"cuisiner","es-g34-u05.w.5":"dessiner","es-g34-u05.w.6":"travailler","es-g34-u05.w.7":"nager","es-g34-u05.w.8":"musique","es-g34-u05.w.9":"piscine","es-g34-u05.s.0":"Je parle espagnol.","es-g34-u05.s.1":"Tu étudies beaucoup.","es-g34-u05.s.2":"Elle écoute de la musique.","es-g34-u05.s.3":"Nous marchons jusqu'au parc.","es-g34-u05.s.4":"Mon papa prépare le dîner.","es-g34-u05.s.5":"Les enfants dessinent des animaux.","es-g34-u05.s.6":"Maman travaille le lundi.","es-g34-u05.s.7":"Nous nageons à la piscine.","es-g34-u05.g.title":"Le présent des verbes réguliers en -ar","es-g34-u05.g.x.0":"Pour les verbes en -ar, on enlève -ar et on ajoute la fin qui va avec la personne : habl-o, habl-as, habl-a, habl-amos, habl-an.","es-g34-u05.g.x.1":"yo hablo (je parle), tú hablas (tu parles), él/ella habla (il/elle parle), nosotros hablamos (nous parlons), ellos hablan (ils parlent).","es-g34-u05.g.x.2":"Estudiar, caminar et cocinar changent exactement pareil.","es-g34-u05.g.0":"Je parle avec ma grand-mère.","es-g34-u05.g.1":"Tu marches vite.","es-g34-u05.g.2":"Elle dessine très bien.","es-g34-u05.g.3":"Nous nageons tous les samedis.","es-g34-u05.g.4":"Ils écoutent la maîtresse.","es-g34-u05.g.5":"Elle étudie l'anglais.","es-g34-u05.g.5.task":"Récris la phrase en commençant par « Ella »","es-g34-u05.g.6":"Nous travaillons à la maison.","es-g34-u05.g.6.task":"Récris la phrase en commençant par « Nosotros »","es-g34-u05.g.7":"Tu prépares le dîner.","es-g34-u05.g.7.task":"Récris la phrase en commençant par « Tú »","es-g34-u06.title":"Les verbes en -er et -ir : como, vivo","es-g34-u06.tip":"Les verbes en -er et en -ir sont presque pareils. Seul « nous » change : comemos / vivimos.","es-g34-u06.w.0":"manger","es-g34-u06.w.1":"boire","es-g34-u06.w.2":"lire","es-g34-u06.w.3":"apprendre","es-g34-u06.w.4":"courir","es-g34-u06.w.5":"habiter","es-g34-u06.w.6":"écrire","es-g34-u06.w.7":"ouvrir","es-g34-u06.w.8":"lettre","es-g34-u06.w.9":"conte","es-g34-u06.s.0":"Je mange du riz.","es-g34-u06.s.1":"Tu bois du lait.","es-g34-u06.s.2":"Elle lit un conte.","es-g34-u06.s.3":"Nous apprenons l'espagnol.","es-g34-u06.s.4":"J'habite à Lima.","es-g34-u06.s.5":"Il écrit une lettre.","es-g34-u06.s.6":"Les enfants courent vite.","es-g34-u06.s.7":"Nous ouvrons la fenêtre.","es-g34-u06.g.title":"Le présent des verbes réguliers en -er / -ir","es-g34-u06.g.x.0":"Verbes en -er : com-o, com-es, com-e, com-emos, com-en.","es-g34-u06.g.x.1":"Verbes en -ir : viv-o, viv-es, viv-e, viv-imos, viv-en. Seul « nous » est différent, avec -imos.","es-g34-u06.g.x.2":"Compare avec -ar : tú hablas / tú comes / tú vives. Retiens que le a devient e.","es-g34-u06.g.0":"Je mange du pain.","es-g34-u06.g.1":"Tu lis beaucoup de livres.","es-g34-u06.g.2":"Elle habite à Madrid.","es-g34-u06.g.3":"Nous habitons ici.","es-g34-u06.g.4":"Ils boivent de l'eau.","es-g34-u06.g.5":"Nous mangeons ensemble.","es-g34-u06.g.5.task":"Récris la phrase avec « Nosotros … juntos »","es-g34-u06.g.6":"Elle écrit une lettre.","es-g34-u06.g.6.task":"Récris la phrase en commençant par « Ella »","es-g34-u06.g.7":"Tu ouvres la porte.","es-g34-u06.g.7.task":"Récris la phrase en commençant par « Tú »","es-g34-u07.title":"J'aime… : gustar","es-g34-u07.tip":"Gusta/gustan s'accorde avec la chose qu'on aime, pas avec « moi ». Plusieurs choses : gustan !","es-g34-u07.w.0":"chocolat","es-g34-u07.w.1":"football","es-g34-u07.w.2":"film","es-g34-u07.w.3":"sport","es-g34-u07.w.4":"légume","es-g34-u07.w.5":"dessert","es-g34-u07.w.6":"devoirs","es-g34-u07.w.7":"préféré","es-g34-u07.w.8":"danser","es-g34-u07.w.9":"chanter","es-g34-u07.s.0":"J'aime le chocolat.","es-g34-u07.s.1":"J'aime le sport.","es-g34-u07.s.2":"Tu aimes le football ?","es-g34-u07.s.3":"Je n'aime pas les légumes.","es-g34-u07.s.4":"Mateo aime danser.","es-g34-u07.s.5":"Mon dessert préféré, c'est la glace.","es-g34-u07.s.6":"Nous aimons regarder des films.","es-g34-u07.s.7":"Je n'aime pas les devoirs.","es-g34-u07.g.title":"Gustar : me gusta / me gustan","es-g34-u07.g.x.0":"« J'aime » se dit me gusta. Si on aime une seule chose, c'est gusta ; si on en aime plusieurs, c'est gustan.","es-g34-u07.g.x.1":"Me gusta el helado. / Me gustan las fresas.","es-g34-u07.g.x.2":"Tu aimes : te gusta ; il/elle aime : le gusta ; nous aimons : nos gusta. Avec un prénom, on dit A Ana le gusta…","es-g34-u07.g.x.3":"Quand on aime faire quelque chose, c'est toujours gusta : Me gusta bailar.","es-g34-u07.g.0":"J'aime le chocolat.","es-g34-u07.g.1":"J'aime les films.","es-g34-u07.g.2":"Tu aimes le football ?","es-g34-u07.g.3":"Lucía aime chanter.","es-g34-u07.g.4":"Nous aimons la musique.","es-g34-u07.g.5":"J'aime le sport.","es-g34-u07.g.5.task":"Récris la phrase avec « los deportes » (au pluriel)","es-g34-u07.g.6":"Je n'aime pas les devoirs.","es-g34-u07.g.6.task":"Mets la phrase à la forme négative (no)","es-g34-u07.g.7":"Tu aimes les légumes ?","es-g34-u07.g.7.task":"Transforme en question avec « ¿Te…? »","es-g34-u07.st.title":"L'heure du goûter","es-g34-u07.st.l.0":"Hugo, tu aimes le chocolat ?","es-g34-u07.st.l.1":"Oui ! J'adore ça. Et toi ?","es-g34-u07.st.l.2":"Moi, j'aime les fraises. C'est mon dessert préféré.","es-g34-u07.st.l.3":"Tu aimes les légumes ?","es-g34-u07.st.l.4":"Non, je n'aime pas ça. Mais j'aime la soupe.","es-g34-u07.st.l.5":"Ma maman adore faire de la soupe. Viens chez moi !","es-g34-u07.st.q.0":"Quel est le dessert préféré de Sofía ?","es-g34-u07.st.q.0.o.0":"Le chocolat","es-g34-u07.st.q.0.o.1":"Les fraises","es-g34-u07.st.q.0.o.2":"La soupe","es-g34-u07.st.q.1":"Qu'est-ce que Sofía n'aime pas ?","es-g34-u07.st.q.1.o.0":"La soupe","es-g34-u07.st.q.1.o.1":"Les fraises","es-g34-u07.st.q.1.o.2":"Les légumes","es-g34-u08.title":"À moi, à toi : mi, tu, su","es-g34-u08.tip":"Tu (ton) n'a pas d'accent, mais tú (toi) en a un. « Tú tienes tu libro » : tu as ton livre.","es-g34-u08.w.0":"jouet","es-g34-u08.w.1":"vélo","es-g34-u08.w.2":"animal de compagnie","es-g34-u08.w.3":"voisin","es-g34-u08.w.4":"cousin","es-g34-u08.w.5":"oncle","es-g34-u08.w.6":"tante","es-g34-u08.w.7":"chambre","es-g34-u08.w.8":"téléphone","es-g34-u08.w.9":"argent","es-g34-u08.s.0":"Mon animal de compagnie est un chien.","es-g34-u08.s.1":"Ton vélo est neuf.","es-g34-u08.s.2":"Sa chambre est grande.","es-g34-u08.s.3":"Notre maison est tout près.","es-g34-u08.s.4":"Mes cousins habitent au Chili.","es-g34-u08.s.5":"Où est ton téléphone ?","es-g34-u08.s.6":"Ma tante a deux chats.","es-g34-u08.s.7":"Ses jouets sont dans la boîte.","es-g34-u08.g.title":"Les possessifs mi / tu / su / nuestro","es-g34-u08.g.x.0":"Mon = mi, ton = tu, son/sa = su, notre = nuestro/nuestra.","es-g34-u08.g.x.1":"Si ce qui suit est au pluriel, on ajoute -s : mis libros, tus zapatos, sus gatos.","es-g34-u08.g.x.2":"Seul nuestro change au féminin : nuestro perro, nuestra casa.","es-g34-u08.g.0":"Mon animal de compagnie est un chat.","es-g34-u08.g.1":"Tes chaussures sont neuves.","es-g34-u08.g.2":"Son cousin habite au Mexique.","es-g34-u08.g.3":"Notre maison est jolie.","es-g34-u08.g.4":"Nos voisins sont gentils.","es-g34-u08.g.5":"Mes jouets sont ici.","es-g34-u08.g.5.task":"Mets au pluriel","es-g34-u08.g.6":"Ton téléphone est neuf.","es-g34-u08.g.6.task":"Récris la phrase avec « Tu » (ton)","es-g34-u08.g.7":"Sa tante habite tout près.","es-g34-u08.g.7.task":"Récris la phrase avec « Su » (sa)","es-g34-u09.title":"Quoi ? Qui ? Où ? : poser des questions","es-g34-u09.tip":"Pour une question, mets toujours le point d'interrogation à l'envers ¿ au début. Et monte la voix à la fin !","es-g34-u09.w.0":"quoi","es-g34-u09.w.1":"qui","es-g34-u09.w.2":"où","es-g34-u09.w.3":"quand","es-g34-u09.w.4":"comment","es-g34-u09.w.5":"combien","es-g34-u09.w.6":"pourquoi","es-g34-u09.w.7":"réponse","es-g34-u09.w.8":"question","es-g34-u09.w.9":"coûter","es-g34-u09.s.0":"Qu'est-ce que c'est ?","es-g34-u09.s.1":"Qui est-ce ?","es-g34-u09.s.2":"Où habites-tu ?","es-g34-u09.s.3":"C'est quand, la fête ?","es-g34-u09.s.4":"Comment tu t'appelles ?","es-g34-u09.s.5":"Combien coûte ce livre ?","es-g34-u09.s.6":"Pourquoi tu pleures ?","es-g34-u09.s.7":"J'ai une question.","es-g34-u09.g.title":"Les mots pour questionner : qué, quién, dónde, cuándo, cómo, cuánto","es-g34-u09.g.x.0":"Tous les mots de question ont un accent : qué (quoi), quién (qui), dónde (où), cuándo (quand), cómo (comment), cuánto (combien).","es-g34-u09.g.x.1":"Une question commence par ¿ et finit par ? : ¿Dónde está el gato?","es-g34-u09.g.x.2":"Le verbe vient en général juste après le mot de question : ¿Qué comes? ¿Quién canta?","es-g34-u09.g.0":"Qu'est-ce que tu manges ?","es-g34-u09.g.1":"Qui est ton ami ?","es-g34-u09.g.2":"Où est mon sac à dos ?","es-g34-u09.g.3":"C'est quand, ton anniversaire ?","es-g34-u09.g.4":"Comment ça va ?","es-g34-u09.g.4.task":"Transforme en question avec « ¿Cómo…? »","es-g34-u09.g.5":"Combien ça coûte ?","es-g34-u09.g.6":"Où habite Lucía ?","es-g34-u09.g.6.task":"Transforme en question avec « ¿Dónde…? »","es-g34-u09.g.7":"Qu'est-ce que Mateo lit ?","es-g34-u09.g.7.task":"Transforme en question avec « ¿Qué…? »","es-g34-u10.title":"Non, je ne fais pas : la négation","es-g34-u10.tip":"En espagnol, on met deux mots négatifs, comme dans « No … nada », et c'est tout à fait correct. Un peu comme « ne … rien » en français !","es-g34-u10.w.0":"rien","es-g34-u10.w.1":"jamais","es-g34-u10.w.2":"personne","es-g34-u10.w.3":"toujours","es-g34-u10.w.4":"aussi","es-g34-u10.w.5":"non plus","es-g34-u10.w.6":"encore","es-g34-u10.w.7":"déjà","es-g34-u10.w.8":"mensonge","es-g34-u10.w.9":"vérité","es-g34-u10.s.0":"Je n'ai pas faim.","es-g34-u10.s.1":"Je n'aime pas le froid.","es-g34-u10.s.2":"Je ne veux rien.","es-g34-u10.s.3":"Je ne suis jamais en retard.","es-g34-u10.s.4":"Il n'y a personne ici.","es-g34-u10.s.5":"Moi non plus, je n'y vais pas.","es-g34-u10.s.6":"Je ne sais pas encore lire.","es-g34-u10.s.7":"Ce n'est pas vrai.","es-g34-u10.g.title":"La négation : no + verbe, nada, nunca, nadie","es-g34-u10.g.x.0":"Pour dire « ne … pas », on met no devant le verbe : No como. No tengo gato.","es-g34-u10.g.x.1":"Quand nada (rien), nadie (personne) ou nunca (jamais) vient après le verbe, on garde aussi no : No veo nada.","es-g34-u10.g.x.2":"« Moi aussi » se dit también, et « moi non plus » se dit tampoco.","es-g34-u10.g.0":"Je n'ai pas faim.","es-g34-u10.g.1":"Je ne vois rien.","es-g34-u10.g.2":"Il n'y a personne à la maison.","es-g34-u10.g.3":"Je ne mange jamais de bonbons.","es-g34-u10.g.4":"Moi non plus, je n'en veux pas.","es-g34-u10.g.5":"Je n'aime pas la pluie.","es-g34-u10.g.5.task":"Mets la phrase à la forme négative (no)","es-g34-u10.g.6":"Elle ne mange pas de viande.","es-g34-u10.g.6.task":"Mets la phrase à la forme négative (no)","es-g34-u10.g.7":"Je ne veux rien.","es-g34-u10.g.7.task":"Mets la phrase à la forme négative avec « nada »","es-g34-u11.title":"Il y a : hay","es-g34-u11.tip":"Hay veut dire « il y a » ; está dit où se trouve quelque chose. Hay un gato (il y a un chat) / El gato está aquí (le chat est ici).","es-g34-u11.w.0":"marché","es-g34-u11.w.1":"magasin","es-g34-u11.w.2":"pain","es-g34-u11.w.3":"œufs","es-g34-u11.w.4":"fruit","es-g34-u11.w.5":"lait","es-g34-u11.w.6":"sac","es-g34-u11.w.7":"frigo","es-g34-u11.w.8":"beaucoup","es-g34-u11.w.9":"peu","es-g34-u11.s.0":"Il y a un chat dans le jardin.","es-g34-u11.s.1":"Il y a beaucoup de fruits au marché.","es-g34-u11.s.2":"Il n'y a pas de lait dans le frigo.","es-g34-u11.s.3":"Il y a du pain ?","es-g34-u11.s.4":"Il y a six œufs dans le sac.","es-g34-u11.s.5":"Il n'y a qu'un peu d'eau.","es-g34-u11.s.6":"Il y a vingt enfants dans ma classe.","es-g34-u11.s.7":"Il y a un magasin tout près.","es-g34-u11.g.title":"Hay : il y a / il n'y a pas","es-g34-u11.g.x.0":"« Il y a » se dit avec un seul mot : hay. C'est pareil pour une chose ou pour plusieurs : Hay un gato. Hay tres gatos.","es-g34-u11.g.x.1":"S'il n'y en a pas, on dit No hay : No hay leche.","es-g34-u11.g.x.2":"Pour la quantité, mucho/mucha (beaucoup) et poco/poca (peu) s'accordent avec le nom : mucha fruta, pocos huevos.","es-g34-u11.g.0":"Il y a un chien dans la rue.","es-g34-u11.g.1":"Il y a beaucoup de magasins ici.","es-g34-u11.g.2":"Il n'y a pas de pain.","es-g34-u11.g.3":"Il y a beaucoup de fruits.","es-g34-u11.g.4":"Il n'y a que peu d'œufs.","es-g34-u11.g.5":"Il n'y a pas de lait à la maison.","es-g34-u11.g.5.task":"Mets la phrase à la forme négative (no)","es-g34-u11.g.6":"Il y a un frigo ici ?","es-g34-u11.g.6.task":"Transforme en question","es-g34-u11.g.7":"Il y a beaucoup d'enfants au parc.","es-g34-u11.g.7.task":"Récris la phrase avec « muchos » (beaucoup)","es-g34-u12.title":"J'ai faim, j'ai soif : les expressions avec tener","es-g34-u12.tip":"Pour demander l'âge, on dit « ¿Cuántos años tienes? » (quel âge as-tu ?). On répond « Tengo … años. »","es-g34-u12.w.0":"faim","es-g34-u12.w.1":"soif","es-g34-u12.w.2":"sommeil","es-g34-u12.w.3":"peur","es-g34-u12.w.4":"hâte","es-g34-u12.w.5":"chance","es-g34-u12.w.6":"raison","es-g34-u12.w.7":"ans","es-g34-u12.w.8":"sandwich","es-g34-u12.w.9":"couverture","es-g34-u12.s.0":"J'ai faim.","es-g34-u12.s.1":"Tu as soif ?","es-g34-u12.s.2":"J'ai neuf ans.","es-g34-u12.s.3":"Ma petite sœur a sommeil.","es-g34-u12.s.4":"Nous sommes pressés.","es-g34-u12.s.5":"Je n'ai pas peur.","es-g34-u12.s.6":"Tu as raison.","es-g34-u12.s.7":"J'ai froid, j'ai besoin d'une couverture.","es-g34-u12.g.title":"Les expressions avec tener : tengo hambre, tengo años","es-g34-u12.g.x.0":"Tener veut dire « avoir », et en espagnol on « a » aussi la faim, la soif et l'âge : Tengo hambre. Tengo diez años.","es-g34-u12.g.x.1":"tengo, tienes, tiene, tenemos, tienen. Seul yo est spécial, avec tengo.","es-g34-u12.g.x.2":"tener frío (avoir froid), tener calor (avoir chaud), tener sueño (avoir sommeil), tener miedo (avoir peur), tener prisa (être pressé), tener razón (avoir raison).","es-g34-u12.g.0":"J'ai faim.","es-g34-u12.g.1":"Tu as soif ?","es-g34-u12.g.2":"Elle a huit ans.","es-g34-u12.g.3":"Nous sommes pressés.","es-g34-u12.g.4":"Ils ont peur.","es-g34-u12.g.5":"Mon grand-père a soixante-dix ans.","es-g34-u12.g.5.task":"Récris la phrase avec « Mi abuelo … setenta »","es-g34-u12.g.6":"Je n'ai pas sommeil.","es-g34-u12.g.6.task":"Mets la phrase à la forme négative (no)","es-g34-u12.g.7":"Tu as froid ?","es-g34-u12.g.7.task":"Transforme en question avec « ¿Tú…? »","es-g34-u12.st.title":"La récré","es-g34-u12.st.l.0":"J'ai trop faim. Tu as un sandwich ?","es-g34-u12.st.l.1":"Oui, j'en ai deux. Prends-en un.","es-g34-u12.st.l.2":"Merci ! J'ai soif aussi.","es-g34-u12.st.l.3":"Il y a de l'eau à la fontaine. Quel âge as-tu, Pablo ?","es-g34-u12.st.l.4":"Neuf ans. Et toi ?","es-g34-u12.st.l.5":"Moi, j'ai dix ans. Dépêchons-nous, le cours va commencer !","es-g34-u12.st.q.0":"Qu'est-ce que Pablo veut ?","es-g34-u12.st.q.0.o.0":"Un livre","es-g34-u12.st.q.0.o.1":"Un sandwich et de l'eau","es-g34-u12.st.q.0.o.2":"Un ballon","es-g34-u12.st.q.1":"Quel âge a Marta ?","es-g34-u12.st.q.1.o.0":"Neuf ans","es-g34-u12.st.q.1.o.1":"Dix ans","es-g34-u12.st.q.1.o.2":"Huit ans","es-g34-u13.title":"Ser ou estar ?","es-g34-u13.tip":"Si tu hésites, demande-toi : « C'est comme ça pour de bon ? » → ser. « C'est comme ça en ce moment ? C'est un lieu ? » → estar.","es-g34-u13.w.0":"ennuyeux","es-g34-u13.w.1":"amusant","es-g34-u13.w.2":"malade","es-g34-u13.w.3":"en bonne santé","es-g34-u13.w.4":"ouvert","es-g34-u13.w.5":"fermé","es-g34-u13.w.6":"chaud","es-g34-u13.w.7":"froid","es-g34-u13.w.8":"jeune","es-g34-u13.w.9":"gentil","es-g34-u13.s.0":"Ma maîtresse est jeune et gentille.","es-g34-u13.s.1":"Aujourd'hui, je suis malade.","es-g34-u13.s.2":"La soupe est chaude.","es-g34-u13.s.3":"Ce jeu est amusant.","es-g34-u13.s.4":"Le magasin est fermé.","es-g34-u13.s.5":"Lucía est péruvienne.","es-g34-u13.s.6":"Nous sommes à l'école.","es-g34-u13.s.7":"La glace est froide.","es-g34-u13.g.title":"Faire la différence entre ser et estar","es-g34-u13.g.x.0":"ser = comment on est pour de bon (nom, métier, pays, caractère, heure) : Soy alto. Es profesora. Son las dos.","es-g34-u13.g.x.1":"estar = l'état, le lieu ou l'humeur en ce moment : Estoy enfermo. Está en casa. Están contentos.","es-g34-u13.g.x.2":"Le même mot peut changer de sens : Es aburrido (c'est quelqu'un d'ennuyeux) / Está aburrido (il s'ennuie en ce moment).","es-g34-u13.g.0":"Mon papa est médecin.","es-g34-u13.g.1":"Aujourd'hui, je suis fatigué.","es-g34-u13.g.2":"La porte est ouverte.","es-g34-u13.g.3":"Nous sommes mexicains.","es-g34-u13.g.4":"Le café est chaud.","es-g34-u13.g.5":"Elle est malade.","es-g34-u13.g.5.task":"Récris la phrase avec « enferma » (malade)","es-g34-u13.g.6":"Le magasin est fermé.","es-g34-u13.g.6.task":"Récris la phrase avec « cerrada » (fermée)","es-g34-u13.g.7":"Mes amis sont amusants.","es-g34-u13.g.7.task":"Mets au pluriel","es-g34-u14.title":"Où vas-tu ? ir + a","es-g34-u14.tip":"« ¿Adónde vas? » veut dire « où vas-tu ? ». La réponse commence par Voy a…","es-g34-u14.w.0":"aller","es-g34-u14.w.1":"cinéma","es-g34-u14.w.2":"plage","es-g34-u14.w.3":"supermarché","es-g34-u14.w.4":"musée","es-g34-u14.w.5":"gare","es-g34-u14.w.6":"montagne","es-g34-u14.w.7":"restaurant","es-g34-u14.w.8":"zoo","es-g34-u14.w.9":"week-end","es-g34-u14.s.0":"Je vais à la plage.","es-g34-u14.s.1":"Où vas-tu ?","es-g34-u14.s.2":"Nous allons au cinéma.","es-g34-u14.s.3":"Maman va au supermarché.","es-g34-u14.s.4":"Mes amis vont au zoo.","es-g34-u14.s.5":"Le week-end, nous allons à la montagne.","es-g34-u14.s.6":"Je vais à la gare à vélo.","es-g34-u14.s.7":"Tu vas au musée aujourd'hui ?","es-g34-u14.g.title":"Le verbe ir avec a / al","es-g34-u14.g.x.0":"« Aller » se dit ir : voy, vas, va, vamos, van. Il change beaucoup, alors apprends-le par cœur.","es-g34-u14.g.x.1":"Pour dire où on va, on utilise a : Voy a la playa.","es-g34-u14.g.x.2":"a + el devient al : Voy al cine. (a el cine ✗)","es-g34-u14.g.0":"Je vais à l'école.","es-g34-u14.g.1":"Tu vas au parc ?","es-g34-u14.g.2":"Elle va au supermarché.","es-g34-u14.g.2.task":"Récris la phrase en commençant par « Ella »","es-g34-u14.g.3":"Nous allons au cinéma.","es-g34-u14.g.4":"Je vais au musée.","es-g34-u14.g.5":"Je vais à la plage.","es-g34-u14.g.6":"Nous allons au zoo.","es-g34-u14.g.6.task":"Récris la phrase en commençant par « Nosotros »","es-g34-u14.g.7":"Ils vont à la montagne.","es-g34-u14.g.7.task":"Récris la phrase en commençant par « Ellos »","es-g34-u14.st.title":"Projets pour le week-end","es-g34-u14.st.l.0":"Elena, où vas-tu samedi ?","es-g34-u14.st.l.1":"Je vais au zoo avec ma famille. Et toi ?","es-g34-u14.st.l.2":"Moi, je vais à la plage. Il fait chaud.","es-g34-u14.st.l.3":"La chance ! Dimanche, nous allons au cinéma. Tu viens ?","es-g34-u14.st.l.4":"Oui, je viens avec vous. À quelle heure ?","es-g34-u14.st.l.5":"À cinq heures. À dimanche !","es-g34-u14.st.q.0":"Où va Carlos samedi ?","es-g34-u14.st.q.0.o.0":"Au zoo","es-g34-u14.st.q.0.o.1":"À la plage","es-g34-u14.st.q.0.o.2":"Au cinéma","es-g34-u14.st.q.1":"À quelle heure est le film dimanche ?","es-g34-u14.st.q.1.o.0":"À trois heures","es-g34-u14.st.q.1.o.1":"À quatre heures","es-g34-u14.st.q.1.o.2":"À cinq heures","es-g34-u15.title":"Quelle heure est-il ?","es-g34-u15.tip":"Regarde une horloge et dis Son las… N'oublie pas : pour une heure seulement, on dit Es la una !","es-g34-u15.w.0":"heure","es-g34-u15.w.1":"horloge","es-g34-u15.w.2":"minute","es-g34-u15.w.3":"midi","es-g34-u15.w.4":"minuit","es-g34-u15.w.5":"tôt","es-g34-u15.w.6":"tard","es-g34-u15.w.7":"petit-déjeuner","es-g34-u15.w.8":"dîner","es-g34-u15.w.9":"récré","es-g34-u15.s.0":"Quelle heure est-il ?","es-g34-u15.s.1":"Il est une heure.","es-g34-u15.s.2":"Il est trois heures.","es-g34-u15.s.3":"Il est cinq heures et demie.","es-g34-u15.s.4":"Il est huit heures et quart.","es-g34-u15.s.5":"Le petit-déjeuner est à sept heures.","es-g34-u15.s.6":"La récré est à onze heures.","es-g34-u15.s.7":"Je me lève tôt.","es-g34-u15.g.title":"Dire l'heure : Es la una / Son las dos","es-g34-u15.g.x.0":"Pour une heure, c'est Es la una ; à partir de deux heures, c'est Son las dos, Son las tres…","es-g34-u15.g.x.1":"On ajoute les minutes avec y : Son las dos y diez (2 h 10). Et demie, c'est y media ; et quart, c'est y cuarto.","es-g34-u15.g.x.2":"« À … heures » se dit a las : La clase es a las nueve.","es-g34-u15.g.0":"Il est une heure.","es-g34-u15.g.1":"Il est quatre heures.","es-g34-u15.g.2":"Il est six heures et demie.","es-g34-u15.g.3":"Il est neuf heures et quart.","es-g34-u15.g.4":"Le dîner est à huit heures.","es-g34-u15.g.5":"Il est dix heures.","es-g34-u15.g.5.task":"Change l'heure pour une heure plus tard","es-g34-u15.g.6":"La récré est à onze heures.","es-g34-u15.g.6.task":"Récris la phrase avec « once » (onze heures)","es-g34-u15.g.7":"Il est une heure et demie.","es-g34-u15.g.7.task":"Ajoute « y media » (et demie)","es-g34-u16.title":"Ceci, cela : este, ese, aquel","es-g34-u16.tip":"Montre avec ta main. Si c'est dans ta main, c'est este ; si c'est près de ton ami, c'est ese ; si c'est très loin, c'est aquel !","es-g34-u16.w.0":"ce (ici)","es-g34-u16.w.1":"ce (là)","es-g34-u16.w.2":"ce (là-bas)","es-g34-u16.w.3":"chemise","es-g34-u16.w.4":"jupe","es-g34-u16.w.5":"casquette","es-g34-u16.w.6":"prix","es-g34-u16.w.7":"pas cher","es-g34-u16.w.8":"cher","es-g34-u16.w.9":"taille","es-g34-u16.s.0":"Ce livre est à moi.","es-g34-u16.s.1":"Cette chemise est jolie.","es-g34-u16.s.2":"Cette montagne là-bas est haute.","es-g34-u16.s.3":"Combien coûte cette casquette ?","es-g34-u16.s.4":"Cette montre est très chère.","es-g34-u16.s.5":"Ces chaussures ne sont pas chères.","es-g34-u16.s.6":"Je veux cette jupe bleue.","es-g34-u16.s.7":"C'est quelle taille ?","es-g34-u16.g.title":"Les démonstratifs : este (ce…-ci), ese (ce…-là), aquel (ce… là-bas)","es-g34-u16.g.x.0":"Tout près : este ; un peu plus loin : ese ; très loin : aquel.","es-g34-u16.g.x.1":"Ils s'accordent avec le nom : este libro / esta casa / estos libros / estas casas.","es-g34-u16.g.x.2":"ese → esa, esos, esas / aquel → aquella, aquellos, aquellas.","es-g34-u16.g.0":"Ce livre est neuf.","es-g34-u16.g.1":"Cette chemise est blanche.","es-g34-u16.g.2":"Ce chien-là est grand.","es-g34-u16.g.3":"Cette maison là-bas est vieille.","es-g34-u16.g.4":"Ces chaussures sont chères.","es-g34-u16.g.5":"Ces casquettes-là ne sont pas chères.","es-g34-u16.g.5.task":"Mets au pluriel","es-g34-u16.g.6":"Cette jupe-là est jolie.","es-g34-u16.g.6.task":"Récris la phrase avec « esa » (cette…-là)","es-g34-u16.g.7":"Cet arbre là-bas est haut.","es-g34-u16.g.7.task":"Récris la phrase avec « aquel » (ce… là-bas)","es-g34-u17.title":"Je veux, je peux : querer, poder","es-g34-u17.tip":"« ¿Puedo…? » sert à demander la permission. ¿Puedo entrar? ¿Puedo salir?","es-g34-u17.w.0":"vouloir","es-g34-u17.w.1":"pouvoir","es-g34-u17.w.2":"jouer","es-g34-u17.w.3":"dormir","es-g34-u17.w.4":"aider","es-g34-u17.w.5":"sortir","es-g34-u17.w.6":"entrer","es-g34-u17.w.7":"peindre","es-g34-u17.w.8":"voler","es-g34-u17.w.9":"permission","es-g34-u17.s.0":"Je veux jouer avec toi.","es-g34-u17.s.1":"Tu veux une glace ?","es-g34-u17.s.2":"Aujourd'hui, je ne peux pas sortir.","es-g34-u17.s.3":"Je peux entrer ?","es-g34-u17.s.4":"Les oiseaux peuvent voler.","es-g34-u17.s.5":"Nous voulons peindre le mur.","es-g34-u17.s.6":"Mon petit frère veut dormir.","es-g34-u17.s.7":"Tu peux aider maman ?","es-g34-u17.g.title":"Querer (vouloir) et poder (pouvoir) + infinitif","es-g34-u17.g.x.0":"querer : quiero, quieres, quiere, queremos, quieren. Le e devient ie (sauf avec nosotros).","es-g34-u17.g.x.1":"poder : puedo, puedes, puede, podemos, pueden. Le o devient ue (sauf avec nosotros).","es-g34-u17.g.x.2":"Après, on met le verbe à l'infinitif : Quiero comer. Puedo nadar.","es-g34-u17.g.0":"Je veux jouer.","es-g34-u17.g.1":"Tu veux une glace ?","es-g34-u17.g.2":"Elle peut nager.","es-g34-u17.g.3":"Nous pouvons aider.","es-g34-u17.g.4":"Ils veulent sortir.","es-g34-u17.g.5":"Aujourd'hui, je ne peux pas sortir.","es-g34-u17.g.5.task":"Mets la phrase à la forme négative (no)","es-g34-u17.g.6":"Tu peux peindre avec moi ?","es-g34-u17.g.6.task":"Transforme en question avec « ¿Tú…? »","es-g34-u17.g.7":"Nous voulons dormir.","es-g34-u17.g.7.task":"Récris la phrase en commençant par « Nosotros »","es-g34-u17.st.title":"Je peux aller jouer dehors ?","es-g34-u17.st.l.0":"Maman, je peux aller jouer dehors ?","es-g34-u17.st.l.1":"Tu veux jouer maintenant ? Les devoirs d'abord.","es-g34-u17.st.l.2":"J'ai fini mes devoirs. Je peux t'aider dans la cuisine !","es-g34-u17.st.l.3":"Très bien. Tu peux sortir une heure.","es-g34-u17.st.l.4":"Merci ! Je veux jouer au foot avec Diego.","es-g34-u17.st.q.0":"Que dit maman de faire d'abord ?","es-g34-u17.st.q.0.o.0":"Les devoirs","es-g34-u17.st.q.0.o.1":"Le dîner","es-g34-u17.st.q.0.o.2":"Une sieste","es-g34-u17.st.q.1":"Combien de temps Hugo peut-il sortir ?","es-g34-u17.st.q.1.o.0":"Trente minutes","es-g34-u17.st.q.1.o.1":"Une heure","es-g34-u17.st.q.1.o.2":"Deux heures","es-g34-u18.title":"Les mois, les saisons et la date","es-g34-u18.tip":"Comme en français, le chiffre vient en premier : « 5 de mayo ». Dis ta date d'anniversaire en espagnol !","es-g34-u18.w.0":"janvier","es-g34-u18.w.1":"avril","es-g34-u18.w.2":"juillet","es-g34-u18.w.3":"octobre","es-g34-u18.w.4":"décembre","es-g34-u18.w.5":"printemps","es-g34-u18.w.6":"été","es-g34-u18.w.7":"automne","es-g34-u18.w.8":"hiver","es-g34-u18.w.9":"vacances","es-g34-u18.s.0":"Aujourd'hui, c'est le 3 mai.","es-g34-u18.s.1":"Mon anniversaire est en juillet.","es-g34-u18.s.2":"En hiver, il fait froid.","es-g34-u18.s.3":"Le printemps est magnifique.","es-g34-u18.s.4":"Quel jour sommes-nous ?","es-g34-u18.s.5":"Les vacances, c'est en été.","es-g34-u18.s.6":"En automne, les feuilles tombent.","es-g34-u18.s.7":"Décembre est le dernier mois.","es-g34-u18.g.title":"Dire la date : el + chiffre + de + mois","es-g34-u18.g.x.0":"Pour la date, le chiffre vient d'abord, puis le mois : Hoy es cinco de abril. (le 5 avril)","es-g34-u18.g.x.1":"Seul le premier jour du mois se dit el primero : el primero de enero.","es-g34-u18.g.x.2":"Les mois et les saisons s'écrivent sans majuscule. « En … » se dit en : en julio, en verano.","es-g34-u18.g.0":"Aujourd'hui, c'est le 2 mars.","es-g34-u18.g.1":"Mon anniversaire est le 10 juillet.","es-g34-u18.g.2":"Aujourd'hui, c'est le 1er janvier.","es-g34-u18.g.3":"En été, il fait chaud.","es-g34-u18.g.4":"Les cours commencent en septembre.","es-g34-u18.g.5":"Aujourd'hui, c'est le 5 avril.","es-g34-u18.g.5.task":"Change la date pour le jour suivant","es-g34-u18.g.6":"En hiver, il neige.","es-g34-u18.g.6.task":"Récris la phrase avec « invierno … nieva »","es-g34-u18.g.7":"Mon anniversaire est en décembre.","es-g34-u18.g.7.task":"Récris la phrase avec « diciembre »","es-g34-u19.title":"Toujours, parfois : ma journée","es-g34-u19.tip":"Raconte ta journée en espagnol : Siempre…, normalmente…, a veces…, nunca….","es-g34-u19.w.0":"parfois","es-g34-u19.w.1":"d'habitude","es-g34-u19.w.2":"prendre le petit-déjeuner","es-g34-u19.w.3":"déjeuner","es-g34-u19.w.4":"dîner","es-g34-u19.w.5":"se reposer","es-g34-u19.w.6":"arriver","es-g34-u19.w.7":"regarder","es-g34-u19.w.8":"télévision","es-g34-u19.w.9":"routine","es-g34-u19.s.0":"Je prends toujours mon petit-déjeuner à sept heures.","es-g34-u19.s.1":"Parfois, je déjeune à l'école.","es-g34-u19.s.2":"D'habitude, j'arrive à la maison à quatre heures.","es-g34-u19.s.3":"L'après-midi, je me repose un peu.","es-g34-u19.s.4":"Je ne regarde jamais la télévision le matin.","es-g34-u19.s.5":"Nous dînons à huit heures.","es-g34-u19.s.6":"Tous les samedis, je joue avec mes cousins.","es-g34-u19.s.7":"Ma routine est simple.","es-g34-u19.g.title":"Les mots de fréquence : siempre, normalmente, a veces, nunca","es-g34-u19.g.x.0":"Pour dire à quelle fréquence on fait quelque chose : siempre (toujours) > normalmente (d'habitude) > a veces (parfois) > nunca (jamais).","es-g34-u19.g.x.1":"Ils se mettent souvent au début de la phrase ou devant le verbe : Siempre desayuno. A veces como pizza.","es-g34-u19.g.x.2":"« Tous les … » se dit los + le jour : los lunes, los sábados. « Le matin », c'est por la mañana ; « l'après-midi », c'est por la tarde.","es-g34-u19.g.0":"Je prends toujours le petit-déjeuner avec ma famille.","es-g34-u19.g.1":"Parfois, je mange à l'école.","es-g34-u19.g.2":"Je ne suis jamais en retard.","es-g34-u19.g.2.task":"Récris la phrase avec « nunca » (jamais)","es-g34-u19.g.3":"D'habitude, je dîne à huit heures.","es-g34-u19.g.4":"Tous les lundis, j'ai cours de musique.","es-g34-u19.g.5":"Le matin, je prends le petit-déjeuner.","es-g34-u19.g.6":"Je ne regarde jamais la télévision.","es-g34-u19.g.6.task":"Récris la phrase avec « nunca » (jamais)","es-g34-u19.g.7":"Tous les samedis, je me repose.","es-g34-u19.g.7.task":"Récris la phrase avec « tous les samedis » (los sábados)","es-g34-u20.title":"Et, mais, parce que","es-g34-u20.tip":"Fais des phrases plus longues avec pero et porque : « Quiero…, pero… » / « … porque … »","es-g34-u20.w.0":"mais","es-g34-u20.w.1":"parce que","es-g34-u20.w.2":"aussi","es-g34-u20.w.3":"alors","es-g34-u20.w.4":"content","es-g34-u20.w.5":"fatigué","es-g34-u20.w.6":"difficile","es-g34-u20.w.7":"facile","es-g34-u20.w.8":"pluie","es-g34-u20.w.9":"promenade","es-g34-u20.s.0":"J'ai un chien et un chat.","es-g34-u20.s.1":"Je veux sortir, mais il pleut.","es-g34-u20.s.2":"Je n'y vais pas parce que je suis fatigué.","es-g34-u20.s.3":"Les devoirs sont difficiles, mais je les finis.","es-g34-u20.s.4":"Je suis content parce que c'est vendredi.","es-g34-u20.s.5":"Il pleut, alors pas de promenade.","es-g34-u20.s.6":"J'aime lire et aussi dessiner.","es-g34-u20.s.7":"Le contrôle est facile et court.","es-g34-u20.g.title":"Les mots de liaison y / pero / porque","es-g34-u20.g.x.0":"y (et) relie deux choses : pan y leche. Si le mot suivant commence par i-, y devient e : padres e hijos.","es-g34-u20.g.x.1":"pero (mais) relie des idées contraires : Es pequeño, pero fuerte.","es-g34-u20.g.x.2":"porque (parce que) donne la raison : No salgo porque llueve. Attention, il s'écrit en un seul mot, pas comme la question ¿por qué?","es-g34-u20.g.0":"J'ai du pain et du fromage.","es-g34-u20.g.1":"Il est petit, mais fort.","es-g34-u20.g.2":"Je ne sors pas parce qu'il pleut.","es-g34-u20.g.3":"Les parents et les enfants jouent ensemble.","es-g34-u20.g.4":"Je suis fatigué, alors je me repose.","es-g34-u20.g.5":"Je veux jouer, mais j'ai des devoirs.","es-g34-u20.g.5.task":"Relie en une seule phrase avec « pero »","es-g34-u20.g.6":"Je suis heureux parce que c'est samedi.","es-g34-u20.g.6.task":"Relie en une seule phrase avec « porque »","es-g34-u20.g.7":"J'aime lire et dessiner.","es-g34-u20.g.7.task":"Relie en une seule phrase avec « y »"},t={"es-g56-u01.title":"Je fais, je sors : les verbes irréguliers","es-g56-u01.tip":"Avec « je », ça finit en -go : hago, salgo, pongo, traigo, vengo, digo. Apprends les six comme une chanson.","es-g56-u01.w.0":"faire","es-g56-u01.w.1":"sortir","es-g56-u01.w.2":"mettre","es-g56-u01.w.3":"apporter","es-g56-u01.w.4":"venir","es-g56-u01.w.5":"dire","es-g56-u01.w.6":"connaître (une personne, un lieu)","es-g56-u01.w.7":"devoirs","es-g56-u01.w.8":"cartable","es-g56-u01.w.9":"cour de récré","es-g56-u01.w.10":"goûter","es-g56-u01.w.11":"tôt","es-g56-u01.s.0":"Je fais mes devoirs l'après-midi.","es-g56-u01.s.1":"Je sors de la maison à huit heures.","es-g56-u01.s.2":"Je pose mon cartable sur la chaise.","es-g56-u01.s.3":"J'apporte mon goûter dans la cour.","es-g56-u01.s.4":"Tu viens chez moi aujourd'hui ?","es-g56-u01.s.5":"Je dis toujours la vérité.","es-g56-u01.s.6":"Je connais tous les voisins.","es-g56-u01.s.7":"Ma grande sœur fait son lit tôt.","es-g56-u01.g.title":"Les verbes en -go avec yo : hago, salgo, pongo","es-g56-u01.g.x.0":"hacer, salir, poner, traer, venir, decir finissent en -go seulement avec « je » (yo) : hago, salgo, pongo, traigo, vengo, digo.","es-g56-u01.g.x.1":"Pour les autres personnes, c'est presque régulier : haces, hace, hacemos, hacen / sales, sale, salimos, salen.","es-g56-u01.g.x.2":"venir et decir changent aussi avec tú et él : vienes, viene / dices, dice. conocer donne conozco.","es-g56-u01.g.0":"Je fais mes devoirs à la maison.","es-g56-u01.g.1":"Je sors à trois heures.","es-g56-u01.g.2":"Je mets la table.","es-g56-u01.g.3":"J'apporte le pain.","es-g56-u01.g.4":"Tu viens avec moi.","es-g56-u01.g.5":"Je viens de l'école.","es-g56-u01.g.5.task":"Change pour commencer par « Yo »","es-g56-u01.g.6":"Je dis la vérité.","es-g56-u01.g.6.task":"Change pour commencer par « Yo »","es-g56-u01.g.7":"Nous faisons du sport.","es-g56-u01.g.7.task":"Change pour commencer par « Nosotros »","es-g56-u01.r.ko":"La journée de Mateo","es-g56-u01.r.genre":"Récit du quotidien","es-g56-u01.r.p.0":"Je m'appelle Mateo et j'ai onze ans. Je sors de la maison à huit heures moins le quart. Je mets mes livres et mon goûter dans mon cartable et je dis au revoir à ma grand-mère. L'école est tout près, alors je viens à vélo.","es-g56-u01.r.p.1":"À la récré, je sors dans la cour avec Lucía. Elle apporte toujours des fruits et moi des biscuits. Après les cours, je fais mes devoirs à la bibliothèque. Je connais tous les maîtres, et eux aussi me connaissent.","es-g56-u01.r.p.2":"Le soir, je mets la table et je dîne avec ma famille. Papa dit que je suis très responsable. Demain, je ferai la même chose !","es-g56-u01.r.q.3.o.0":"goûter","es-g56-u01.r.q.3.o.1":"devoirs","es-g56-u01.r.q.3.o.2":"vélo","es-g56-u01.r.q.3.o.3":"bibliothèque","es-g56-u02.title":"e→ie, o→ue : les verbes qui changent","es-g56-u02.tip":"Seul nosotros ne change pas ! « empezamos, volvemos » gardent la voyelle d'origine.","es-g56-u02.w.0":"commencer","es-g56-u02.w.1":"penser","es-g56-u02.w.2":"comprendre","es-g56-u02.w.3":"préférer","es-g56-u02.w.4":"revenir","es-g56-u02.w.5":"compter (raconter)","es-g56-u02.w.6":"se souvenir","es-g56-u02.w.7":"trouver","es-g56-u02.w.8":"déjeuner","es-g56-u02.w.9":"clé","es-g56-u02.w.10":"poche","es-g56-u02.w.11":"leçon","es-g56-u02.s.0":"Le cours commence à neuf heures.","es-g56-u02.s.1":"Je pense à mes grands-parents.","es-g56-u02.s.2":"Je ne comprends pas ce mot.","es-g56-u02.s.3":"Je préfère déjeuner à la maison.","es-g56-u02.s.4":"Je reviens à la maison à cinq heures.","es-g56-u02.s.5":"Je compte les pièces dans ma poche.","es-g56-u02.s.6":"Tu te souviens de la leçon d'hier ?","es-g56-u02.s.7":"Je ne trouve pas mes clés.","es-g56-u02.g.title":"Les verbes à diphtongue : e→ie, o→ue","es-g56-u02.g.x.0":"Dans certains verbes, la voyelle du milieu change. e→ie : empiezo, piensas, entiende, prefieren.","es-g56-u02.g.x.1":"o→ue : vuelvo, cuentas, recuerda, encuentran.","es-g56-u02.g.x.2":"nosotros ne change pas : empezamos, volvemos. Pense à une botte (boot) : seul nosotros reste dehors.","es-g56-u02.g.0":"Le film commence maintenant.","es-g56-u02.g.1":"Je pense à toi.","es-g56-u02.g.2":"Tu comprends la leçon ?","es-g56-u02.g.3":"Nous revenons tard.","es-g56-u02.g.4":"Elle compte jusqu'à dix.","es-g56-u02.g.5":"Je préfère le thé.","es-g56-u02.g.5.task":"Change pour commencer par « Yo »","es-g56-u02.g.6":"Ils reviennent à la maison.","es-g56-u02.g.6.task":"Change pour commencer par « Ellos »","es-g56-u02.g.7":"Je ne me souviens pas de son nom.","es-g56-u02.g.7.task":"Mets à la forme négative (no)","es-g56-u03.title":"Je me lève, je me lave : les verbes réfléchis","es-g56-u03.tip":"Raconte ton matin dans l'ordre : Me despierto, me levanto, me ducho, me visto, me peino.","es-g56-u03.w.0":"se lever","es-g56-u03.w.1":"se doucher","es-g56-u03.w.2":"s'habiller","es-g56-u03.w.3":"se coiffer","es-g56-u03.w.4":"se laver","es-g56-u03.w.5":"se coucher","es-g56-u03.w.6":"se réveiller","es-g56-u03.w.7":"s'asseoir","es-g56-u03.w.8":"brosse à dents","es-g56-u03.w.9":"serviette","es-g56-u03.w.10":"miroir","es-g56-u03.w.11":"pyjama","es-g56-u03.s.0":"Je me lève à sept heures.","es-g56-u03.s.1":"Je me douche et je m'habille vite.","es-g56-u03.s.2":"Mon frère se coiffe devant le miroir.","es-g56-u03.s.3":"Nous nous lavons les mains avant de manger.","es-g56-u03.s.4":"Je me couche à neuf heures et demie.","es-g56-u03.s.5":"À quelle heure tu te réveilles ?","es-g56-u03.s.6":"Les enfants s'assoient par terre.","es-g56-u03.s.7":"Je me sèche avec la serviette bleue.","es-g56-u03.g.title":"Les verbes réfléchis : me levanto, te duchas, se viste","es-g56-u03.g.x.0":"Quand on fait l'action sur soi-même, on met me, te, se, nos, se devant : Me levanto. Te duchas. Se viste.","es-g56-u03.g.x.1":"Si l'infinitif finit par -se, c'est un verbe réfléchi : levantarse, acostarse.","es-g56-u03.g.x.2":"On peut aussi l'accrocher à la fin de l'infinitif : Quiero levantarme. Voy a ducharme.","es-g56-u03.g.0":"Je me lève à sept heures.","es-g56-u03.g.1":"Tu te douches le matin ?","es-g56-u03.g.2":"Elle s'habille toute seule.","es-g56-u03.g.3":"Nous nous brossons les dents.","es-g56-u03.g.4":"Ils se couchent tard.","es-g56-u03.g.5":"Je me réveille à six heures.","es-g56-u03.g.5.task":"Change pour que ça aille avec « Yo »","es-g56-u03.g.6":"Nous nous asseyons ici.","es-g56-u03.g.6.task":"Change pour que ça aille avec « Nosotros »","es-g56-u03.g.7":"Je veux me coucher tôt.","es-g56-u03.g.7.task":"Change en « Quiero + infinitif »","es-g56-u03.r.ko":"Le matin de Sofía","es-g56-u03.r.genre":"Récit du quotidien","es-g56-u03.r.p.0":"Sofía se réveille à sept heures moins dix, mais elle ne se lève pas avant sept heures. D'abord elle se douche à l'eau chaude et se sèche avec sa serviette jaune. Ensuite elle s'habille. Aujourd'hui, elle choisit un pantalon bleu et un t-shirt blanc.","es-g56-u03.r.p.1":"Dans la salle de bain, elle se brosse les dents avec sa brosse verte et se coiffe devant le miroir. Son petit frère Hugo est encore en pyjama. « Dépêche-toi, Hugo ! » dit Sofía. Hugo s'assoit sur son lit et bâille.","es-g56-u03.r.p.2":"À huit heures, tous les deux prennent le petit-déjeuner avec maman. Le soir, Sofía se couche à neuf heures et demie. Avant de dormir, elle lit toujours un peu.","es-g56-u03.r.q.4.o.0":"bâiller","es-g56-u03.r.q.4.o.1":"chanter","es-g56-u03.r.q.4.o.2":"courir","es-g56-u03.r.q.4.o.3":"rire","es-g56-u04.title":"Je vais faire… : ir a + infinitif","es-g56-u04.tip":"Dis tes projets du week-end en espagnol : Voy a…, Vamos a…. Si tu n'as rien prévu : ¡No voy a hacer nada!","es-g56-u04.w.0":"voyager","es-g56-u04.w.1":"visiter","es-g56-u04.w.2":"acheter","es-g56-u04.w.3":"apprendre","es-g56-u04.w.4":"nager","es-g56-u04.w.5":"valise","es-g56-u04.w.6":"billet","es-g56-u04.w.7":"aéroport","es-g56-u04.w.8":"hôtel","es-g56-u04.w.9":"carte (plan)","es-g56-u04.w.10":"prochain","es-g56-u04.w.11":"bientôt","es-g56-u04.s.0":"Je vais voyager au Mexique.","es-g56-u04.s.1":"Nous allons rendre visite à nos grands-parents.","es-g56-u04.s.2":"Tu vas acheter les billets ?","es-g56-u04.s.3":"Ma sœur va apprendre l'espagnol.","es-g56-u04.s.4":"L'été prochain, nous allons beaucoup nager.","es-g56-u04.s.5":"Mes parents vont faire les valises.","es-g56-u04.s.6":"Nous allons bientôt arriver à l'aéroport.","es-g56-u04.s.7":"Je ne vais pas regarder la carte.","es-g56-u04.g.title":"ir a + infinitif : le futur proche","es-g56-u04.g.x.0":"« Je vais faire… » se dit avec ir + a + infinitif : Voy a comer. Vas a leer. Va a dormir.","es-g56-u04.g.x.1":"À plusieurs : Vamos a…, Van a…. La négation : No voy a….","es-g56-u04.g.x.2":"On l'utilise avec des mots de temps : mañana (demain), el próximo año (l'année prochaine), pronto (bientôt), esta noche (ce soir).","es-g56-u04.g.0":"Je vais acheter du pain.","es-g56-u04.g.1":"Tu vas voyager cet été ?","es-g56-u04.g.2":"Elle va visiter le musée.","es-g56-u04.g.3":"Nous allons nager.","es-g56-u04.g.4":"Ils vont bientôt arriver.","es-g56-u04.g.5":"Demain, je vais apprendre à nager.","es-g56-u04.g.5.task":"Change en « Mañana voy a… »","es-g56-u04.g.6":"Je ne vais pas acheter de billet.","es-g56-u04.g.6.task":"Mets à la forme négative (no)","es-g56-u04.g.7":"Nous allons rendre visite à nos grands-parents.","es-g56-u04.g.7.task":"Change au futur avec « Vamos a… »","es-g56-u04.r.ko":"Le voyage de la famille de Luis","es-g56-u04.r.genre":"Récit du quotidien","es-g56-u04.r.p.0":"La famille de Luis va voyager au Pérou le mois prochain. Papa a déjà les billets d'avion et maman va réserver l'hôtel ce soir. Diego, qui a douze ans, est très content de voir le Machu Picchu.","es-g56-u04.r.p.1":"Sa petite sœur Carla va acheter une carte et un nouvel appareil photo. « Je vais prendre mille photos », dit Carla. Diego va apprendre dix mots de quechua avant le voyage. Tous les deux vont faire leurs valises vendredi.","es-g56-u04.r.p.2":"Samedi, ils vont partir très tôt pour l'aéroport. « Nous n'allons pas être en retard », dit papa. « Et nous n'allons pas oublier les passeports ! »","es-g56-u04.r.q.3.o.0":"réserver","es-g56-u04.r.q.3.o.1":"acheter","es-g56-u04.r.q.3.o.2":"oublier","es-g56-u04.r.q.3.o.3":"prendre (des photos)","es-g56-u05.title":"Hier, j'ai… : le passé des verbes en -ar","es-g56-u05.tip":"Au passé, yo finit en -é et él en -ó. Sans l'accent, le sens change : canto (je chante) / cantó (il a chanté).","es-g56-u05.w.0":"hier","es-g56-u05.w.1":"hier soir","es-g56-u05.w.2":"dernier","es-g56-u05.w.3":"gagner","es-g56-u05.w.4":"danser","es-g56-u05.w.5":"chanter","es-g56-u05.w.6":"cuisiner","es-g56-u05.w.7":"nettoyer","es-g56-u05.w.8":"match","es-g56-u05.w.9":"équipe","es-g56-u05.w.10":"pique-nique","es-g56-u05.w.11":"anniversaire","es-g56-u05.s.0":"Hier, j'ai joué au foot avec mon équipe.","es-g56-u05.s.1":"Hier soir, j'ai dîné avec mes grands-parents.","es-g56-u05.s.2":"Tu as gagné le match ?","es-g56-u05.s.3":"Ma sœur a dansé à la fête.","es-g56-u05.s.4":"Nous avons chanté à l'anniversaire de Lucía.","es-g56-u05.s.5":"Mes parents ont cuisiné une paella.","es-g56-u05.s.6":"Samedi dernier, j'ai nettoyé ma chambre.","es-g56-u05.s.7":"Le pique-nique s'est terminé à cinq heures.","es-g56-u05.g.title":"Le passé des verbes en -ar : hablé, hablaste, habló","es-g56-u05.g.x.0":"Pour une action finie, on utilise le passé (pretérito). Verbes en -ar : habl-é, habl-aste, habl-ó, habl-amos, habl-aron.","es-g56-u05.g.x.1":"yo finit en -é, él/ella en -ó. L'accent est obligatoire : canté, cantó.","es-g56-u05.g.x.2":"nosotros est pareil qu'au présent (hablamos). Des mots comme ayer, anoche montrent que c'est du passé.","es-g56-u05.g.x.3":"jugar s'écrit jugué avec yo (on ajoute un u pour garder le son).","es-g56-u05.g.0":"Hier, j'ai chanté en classe.","es-g56-u05.g.1":"Tu as dansé hier soir ?","es-g56-u05.g.2":"Mon papa a cuisiné le dîner.","es-g56-u05.g.3":"Nous avons nettoyé la maison hier.","es-g56-u05.g.4":"Ils ont gagné le match.","es-g56-u05.g.5":"Hier, j'ai joué au foot.","es-g56-u05.g.5.task":"Ajoute « Ayer » et mets au passé","es-g56-u05.g.6":"Elle a parlé avec le maître.","es-g56-u05.g.6.task":"Mets au passé","es-g56-u05.g.7":"L'année dernière, nous avons voyagé en train.","es-g56-u05.g.7.task":"Change pour commencer par « Nosotros »","es-g56-u06.title":"J'ai mangé, j'ai vécu : le passé des verbes en -er/-ir","es-g56-u06.tip":"Au passé, -er et -ir sont exactement pareils. comí/viví, comiste/viviste… Une seule série à apprendre !","es-g56-u06.w.0":"perdre","es-g56-u06.w.1":"casser","es-g56-u06.w.2":"apprendre","es-g56-u06.w.3":"courir","es-g56-u06.w.4":"ouvrir","es-g56-u06.w.5":"recevoir","es-g56-u06.w.6":"écrire","es-g56-u06.w.7":"monter","es-g56-u06.w.8":"escalier","es-g56-u06.w.9":"prix (récompense)","es-g56-u06.w.10":"concours","es-g56-u06.w.11":"surprise","es-g56-u06.s.0":"Hier, j'ai perdu mon chapeau au parc.","es-g56-u06.s.1":"Mon petit frère a cassé un verre.","es-g56-u06.s.2":"Nous avons appris une nouvelle chanson.","es-g56-u06.s.3":"Tu as couru la course ?","es-g56-u06.s.4":"J'ai ouvert la porte et j'ai vu la surprise.","es-g56-u06.s.5":"Lucía a reçu un prix au concours.","es-g56-u06.s.6":"J'ai écrit une lettre à mon grand-père.","es-g56-u06.s.7":"Nous avons monté l'escalier en courant.","es-g56-u06.g.title":"Le passé des verbes en -er / -ir : comí, comiste, comió","es-g56-u06.g.x.0":"Au passé, les verbes en -er et en -ir sont identiques : com-í, com-iste, com-ió, com-imos, com-ieron.","es-g56-u06.g.x.1":"viv-í, viv-iste, viv-ió, viv-imos, viv-ieron.","es-g56-u06.g.x.2":"yo finit en -í, él/ella en -ió. N'oublie pas l'accent : perdí, perdió.","es-g56-u06.g.0":"Hier, j'ai mangé une paella.","es-g56-u06.g.1":"Tu as perdu tes clés ?","es-g56-u06.g.2":"Il a cassé la fenêtre.","es-g56-u06.g.3":"Nous avons beaucoup appris.","es-g56-u06.g.4":"Ils ont ouvert les cadeaux.","es-g56-u06.g.5":"Elle a reçu un prix.","es-g56-u06.g.5.task":"Mets au passé","es-g56-u06.g.6":"J'ai écrit une lettre.","es-g56-u06.g.6.task":"Mets au passé","es-g56-u06.g.7":"Hier, nous avons grimpé la montagne.","es-g56-u06.g.7.task":"Change pour commencer par « Nosotros »","es-g56-u06.r.ko":"Le concours de dessin","es-g56-u06.r.genre":"Conte","es-g56-u06.r.p.0":"Lundi dernier, l'école a organisé un concours de dessin. Lucía a dessiné un dragon vert avec de grandes ailes. Pablo a dessiné son chien Toby, mais il a cassé son crayon rouge sans faire exprès et a demandé un autre crayon à la maîtresse.","es-g56-u06.r.p.1":"À la fin de l'après-midi, le directeur a ouvert une enveloppe et a lu un nom. « Le premier prix est pour… Lucía ! » Lucía a reçu une boîte de crayons de couleur et un livre. Pablo n'a pas gagné, mais il a appris quelque chose d'important : dessiner avec soin.","es-g56-u06.r.p.2":"Ce soir-là, Lucía a écrit une lettre à sa grand-mère. « Mamie, j'ai gagné le concours. Quelle surprise ! » Et Pablo a décidé de dessiner un dragon pour l'année prochaine.","es-g56-u07.title":"Mange ! Ouvre ! : l'impératif","es-g56-u07.tip":"L'impératif, c'est court et énergique ! Essaie à la maison : ¡Ven! ¡Mira! ¡Escucha! (avec por favor après, c'est encore mieux)","es-g56-u07.w.0":"écouter","es-g56-u07.w.1":"regarder","es-g56-u07.w.2":"attendre","es-g56-u07.w.3":"fermer","es-g56-u07.w.4":"prendre (boire)","es-g56-u07.w.5":"passer (donner)","es-g56-u07.w.6":"attention","es-g56-u07.w.7":"silence","es-g56-u07.w.8":"lentement","es-g56-u07.w.9":"sel","es-g56-u07.w.10":"recette","es-g56-u07.w.11":"consignes","es-g56-u07.s.0":"Écoute le maître.","es-g56-u07.s.1":"Regarde la carte, s'il te plaît.","es-g56-u07.s.2":"Attends un moment.","es-g56-u07.s.3":"Ferme la fenêtre, il fait froid.","es-g56-u07.s.4":"Bois un verre d'eau.","es-g56-u07.s.5":"Passe-moi le sel, s'il te plaît.","es-g56-u07.s.6":"Parle lentement et avec attention.","es-g56-u07.s.7":"Lis la recette avant de cuisiner.","es-g56-u07.g.title":"L'impératif de tú : ¡Habla! ¡Come! ¡Abre!","es-g56-u07.g.x.0":"Pour dire « fais ça ! » à un ami, on utilise la même forme que él/ella au présent : habla, come, abre, escucha, cierra.","es-g56-u07.g.x.1":"Quelques irréguliers à apprendre par cœur : ten (prends), ven (viens), pon (mets), sal (sors), haz (fais), di (dis).","es-g56-u07.g.x.2":"Les petits mots comme me, la s'accrochent à la fin : Pásame la sal. Ciérrala.","es-g56-u07.g.0":"Écoute la chanson !","es-g56-u07.g.1":"Mange des fruits !","es-g56-u07.g.2":"Ouvre le livre !","es-g56-u07.g.3":"Viens ici, s'il te plaît !","es-g56-u07.g.4":"Mets la table !","es-g56-u07.g.5":"Ferme la porte !","es-g56-u07.g.5.task":"Mets à l'impératif","es-g56-u07.g.6":"Regarde la carte !","es-g56-u07.g.6.task":"Mets à l'impératif","es-g56-u07.g.7":"Fais tes devoirs maintenant !","es-g56-u07.g.7.task":"Mets à l'impératif","es-g56-u08.title":"Plus grand, moins cher : comparer","es-g56-u08.tip":"Compare ta famille et tes amis : Mi papá es más alto que mi mamá. Soy tan rápido como mi amigo.","es-g56-u08.w.0":"plus","es-g56-u08.w.1":"moins","es-g56-u08.w.2":"meilleur","es-g56-u08.w.3":"pire","es-g56-u08.w.4":"plus âgé","es-g56-u08.w.5":"plus jeune","es-g56-u08.w.6":"large","es-g56-u08.w.7":"étroit","es-g56-u08.w.8":"bruyant","es-g56-u08.w.9":"calme","es-g56-u08.w.10":"bâtiment","es-g56-u08.w.11":"habitant","es-g56-u08.s.0":"Madrid est plus grande que Tolède.","es-g56-u08.s.1":"Le village est moins bruyant que la ville.","es-g56-u08.s.2":"Mon frère est plus âgé que moi.","es-g56-u08.s.3":"Ce livre est meilleur que celui-là.","es-g56-u08.s.4":"Cette rue est aussi étroite qu'un couloir.","es-g56-u08.s.5":"J'ai autant de crayons que toi.","es-g56-u08.s.6":"Le nouveau bâtiment est plus haut que l'église.","es-g56-u08.s.7":"Mon petit cousin court plus vite que moi.","es-g56-u08.g.title":"Le comparatif : más … que, menos … que, tan … como","es-g56-u08.g.x.0":"« Plus … que » : más + adjectif + que. Soy más alto que tú.","es-g56-u08.g.x.1":"« Moins … que » : menos + adjectif + que. « Aussi … que » : tan + adjectif + como.","es-g56-u08.g.x.2":"Comparatifs spéciaux : bueno → mejor, malo → peor, grande (âge) → mayor, pequeño (âge) → menor.","es-g56-u08.g.0":"Le lion est plus grand que le chat.","es-g56-u08.g.1":"Le train est moins rapide que l'avion.","es-g56-u08.g.2":"Ma maison est aussi jolie que la tienne.","es-g56-u08.g.3":"Cette glace est meilleure que celle-là.","es-g56-u08.g.4":"Ma sœur est plus âgée que moi.","es-g56-u08.g.5":"La ville est plus bruyante que le village.","es-g56-u08.g.5.task":"Réécris avec « La ciudad … ruidosa »","es-g56-u08.g.6":"Aujourd'hui, il fait moins froid qu'hier.","es-g56-u08.g.6.task":"Réécris avec « menos » (moins)","es-g56-u08.g.7":"Je suis aussi grand que mon cousin.","es-g56-u08.g.7.task":"Réécris avec « tan … como » (aussi … que)","es-g56-u08.r.ko":"Deux villes, deux cousins","es-g56-u08.r.genre":"Texte explicatif","es-g56-u08.r.p.0":"Javier habite à Madrid et sa cousine Elena habite à Cuenca. Madrid est bien plus grande que Cuenca. Elle a plus de trois millions d'habitants, et Cuenca n'en a même pas soixante mille. À Madrid, il y a des bâtiments plus hauts, des rues plus larges et beaucoup plus de bruit.","es-g56-u08.r.p.1":"Cuenca est plus calme et plus ancienne. Ses rues sont si étroites que parfois les voitures ne peuvent pas passer. Elena dit que l'air de Cuenca est meilleur que celui de Madrid. Javier dit que Madrid est plus amusante parce qu'il y a plus de musées et de parcs.","es-g56-u08.r.p.2":"Les deux cousins ont le même âge et sont aussi bons amis que des frères. L'été, Javier visite Cuenca, et l'hiver, Elena visite Madrid. Comme ça, ils connaissent le meilleur de chaque ville.","es-g56-u08.r.q.3.o.0":"ancien","es-g56-u08.r.q.3.o.1":"bruyant","es-g56-u08.r.q.3.o.2":"large","es-g56-u08.r.q.3.o.3":"nouveau","es-g56-u09.title":"Le plus grand, le meilleur : le superlatif","es-g56-u09.tip":"Dis les records du monde en espagnol : el más alto, el más rápido, el más grande del mundo.","es-g56-u09.w.0":"long","es-g56-u09.w.1":"court","es-g56-u09.w.2":"profond","es-g56-u09.w.3":"célèbre","es-g56-u09.w.4":"ancien","es-g56-u09.w.5":"moderne","es-g56-u09.w.6":"délicieux","es-g56-u09.w.7":"dangereux","es-g56-u09.w.8":"monde","es-g56-u09.w.9":"planète","es-g56-u09.w.10":"animal","es-g56-u09.w.11":"désert","es-g56-u09.s.0":"Le Nil est le fleuve le plus long du monde.","es-g56-u09.s.1":"Jupiter est la plus grande planète.","es-g56-u09.s.2":"La baleine bleue est l'animal le plus lourd.","es-g56-u09.s.3":"C'est la pizza la plus délicieuse de la ville.","es-g56-u09.s.4":"Ma grand-mère est la personne la plus gentille que je connaisse.","es-g56-u09.s.5":"C'est le bâtiment le plus ancien du village.","es-g56-u09.s.6":"Le Sahara est le désert le plus célèbre.","es-g56-u09.s.7":"C'est le chemin le moins dangereux.","es-g56-u09.g.title":"Le superlatif : el/la más … de","es-g56-u09.g.x.0":"« Le plus … » se dit el/la/los/las + más + adjectif : el río más largo, la casa más bonita.","es-g56-u09.g.x.1":"« De … » se dit de : el más alto de la clase (le plus grand de la classe).","es-g56-u09.g.x.2":"« Le moins … » se dit avec menos. Formes spéciales : el mejor (le meilleur), el peor (le pire), el mayor (le plus âgé).","es-g56-u09.g.0":"C'est le fleuve le plus long du monde.","es-g56-u09.g.1":"C'est la ville la plus ancienne d'Espagne.","es-g56-u09.g.2":"C'est le meilleur joueur de l'équipe.","es-g56-u09.g.3":"C'est l'animal le plus dangereux de la mer.","es-g56-u09.g.4":"Mon frère est le plus âgé de la famille.","es-g56-u09.g.5":"C'est le chemin le moins dangereux.","es-g56-u09.g.5.task":"Réécris avec « menos » (le moins)","es-g56-u09.g.6":"C'est la montagne la plus haute du pays.","es-g56-u09.g.6.task":"Mets au superlatif « la … más alta del país »","es-g56-u09.g.7":"C'est le gâteau le plus délicieux de la fête.","es-g56-u09.g.7.task":"Mets au superlatif « el … más delicioso de la fiesta »","es-g56-u10.title":"Regarde-le : lo, la, los, las","es-g56-u10.tip":"Regarde le genre et le nombre de l'objet : el libro → lo, la carta → la, los lápices → los, las gafas → las.","es-g56-u10.w.0":"chercher","es-g56-u10.w.1":"emporter","es-g56-u10.w.2":"utiliser","es-g56-u10.w.3":"garder","es-g56-u10.w.4":"prêter","es-g56-u10.w.5":"avoir besoin de","es-g56-u10.w.6":"inviter","es-g56-u10.w.7":"ordinateur","es-g56-u10.w.8":"appareil photo","es-g56-u10.w.9":"lunettes","es-g56-u10.w.10":"parapluie","es-g56-u10.w.11":"portefeuille","es-g56-u10.s.0":"Où est mon portefeuille ? Je ne le trouve pas.","es-g56-u10.s.1":"J'ai besoin du parapluie. Je l'emporte aujourd'hui.","es-g56-u10.s.2":"Les lunettes ? Je les garde dans mon cartable.","es-g56-u10.s.3":"Mes cousins arrivent. Je vais les inviter à dîner.","es-g56-u10.s.4":"Tu me prêtes l'appareil photo ? J'en ai besoin.","es-g56-u10.s.5":"L'ordinateur est vieux, mais je l'utilise tous les jours.","es-g56-u10.s.6":"Je cherche les clés. Tu les vois ?","es-g56-u10.s.7":"Je t'invite à ma fête.","es-g56-u10.g.title":"Les pronoms COD : lo, la, los, las, me, te","es-g56-u10.g.x.0":"Pour ne pas répéter, « le / la » se dit lo (masculin) / la (féminin), et au pluriel los / las : ¿El libro? Lo leo. ¿La carta? La escribo.","es-g56-u10.g.x.1":"« me » se dit me, « te » se dit te : Te invito. Me buscas.","es-g56-u10.g.x.2":"Le pronom va devant le verbe. S'il y a un infinitif, on peut l'accrocher à la fin : Quiero comprarlo.","es-g56-u10.g.0":"Le livre ? Je le lis ce soir.","es-g56-u10.g.1":"La lettre ? Je l'écris demain.","es-g56-u10.g.2":"Les crayons ? Je les garde ici.","es-g56-u10.g.3":"Les lunettes ? J'en ai besoin.","es-g56-u10.g.4":"Je t'invite chez moi.","es-g56-u10.g.5":"Le parapluie ? Je l'emporte.","es-g56-u10.g.5.task":"Remplace « el paraguas » par lo","es-g56-u10.g.6":"L'appareil photo ? Je l'utilise beaucoup.","es-g56-u10.g.6.task":"Remplace « la cámara » par la","es-g56-u10.g.7":"Les cousins ? Je vais les inviter.","es-g56-u10.g.7.task":"Remplace « los primos » par los","es-g56-u11.title":"Je suis en train de… : estar + -ando/-iendo","es-g56-u11.tip":"Regarde autour de toi et dis-le : Mamá está cocinando. El perro está durmiendo. ¿Qué estás haciendo tú?","es-g56-u11.w.0":"maintenant","es-g56-u11.w.1":"encore","es-g56-u11.w.2":"préparer","es-g56-u11.w.3":"construire","es-g56-u11.w.4":"peindre","es-g56-u11.w.5":"jouer (d'un instrument)","es-g56-u11.w.6":"rire","es-g56-u11.w.7":"pleurer","es-g56-u11.w.8":"fête foraine","es-g56-u11.w.9":"guitare","es-g56-u11.w.10":"clown","es-g56-u11.w.11":"ballon","es-g56-u11.s.0":"Maintenant, je suis en train de faire mes devoirs.","es-g56-u11.s.1":"Qu'est-ce que tu es en train de manger ?","es-g56-u11.s.2":"Maman est en train de préparer le dîner.","es-g56-u11.s.3":"Les enfants sont en train de construire un château de sable.","es-g56-u11.s.4":"Mon frère est en train de jouer de la guitare.","es-g56-u11.s.5":"Le clown est en train de rire avec les enfants.","es-g56-u11.s.6":"Nous sommes encore en train de peindre le mur.","es-g56-u11.s.7":"Le bébé pleure parce qu'il a perdu son ballon.","es-g56-u11.g.title":"Le présent progressif : estar + -ando / -iendo","es-g56-u11.g.x.0":"« Je suis en train de… » se dit estar + verbe en -ando (-ar) / -iendo (-er, -ir) : Estoy hablando. Estás comiendo. Está escribiendo.","es-g56-u11.g.x.1":"Entre deux voyelles, le i devient y : leer → leyendo, construir → construyendo. dormir → durmiendo, reír → riendo.","es-g56-u11.g.x.2":"Seul estar change selon la personne ; -ando/-iendo reste pareil.","es-g56-u11.g.0":"Je suis en train de parler avec maman.","es-g56-u11.g.1":"Tu es en train de manger ?","es-g56-u11.g.2":"Elle est en train d'écrire une lettre.","es-g56-u11.g.3":"Nous sommes en train de lire un livre.","es-g56-u11.g.4":"Ils sont en train de construire une maison.","es-g56-u11.g.5":"Mon petit frère est en train de dormir.","es-g56-u11.g.5.task":"Mets au présent progressif (en train de)","es-g56-u11.g.6":"Maintenant, je suis en train de peindre la porte.","es-g56-u11.g.6.task":"Mets au présent progressif avec « Ahora estoy… »","es-g56-u11.g.7":"Les enfants sont en train de rire.","es-g56-u11.g.7.task":"Mets au présent progressif (en train de)","es-g56-u11.r.ko":"La fête du village","es-g56-u11.r.genre":"Texte descriptif","es-g56-u11.r.p.0":"Samedi après-midi, la fête du village est pleine de monde. Sur la place, un clown au nez rouge est en train de faire des animaux en ballons. Les enfants rient et crient : « Un chien ! Une girafe ! »","es-g56-u11.r.p.1":"Près de la fontaine, trois musiciens jouent de la guitare et une dame chante une vieille chanson. Grand-père danse avec grand-mère. Maman prépare un chocolat chaud au stand et papa achète des churros.","es-g56-u11.r.p.2":"Je suis assis sur un banc avec ma petite sœur. Elle dessine dans son cahier ce qu'elle voit. Un bébé pleure parce que son ballon s'est envolé dans le ciel. Tout le monde regarde ce ballon !","es-g56-u11.r.q.3.o.0":"stand","es-g56-u11.r.q.3.o.1":"fontaine","es-g56-u11.r.q.3.o.2":"banc","es-g56-u11.r.q.3.o.3":"place","es-g56-u12.title":"Je suis allé, j'ai fait, j'ai eu : le passé irrégulier","es-g56-u12.tip":"Au passé, ir et ser donnent le même fui ! On comprend grâce au contexte : Fui al cine (je suis allé) / Fui feliz (j'ai été heureux).","es-g56-u12.w.0":"naître","es-g56-u12.w.1":"grandir","es-g56-u12.w.2":"inventer","es-g56-u12.w.3":"découvrir","es-g56-u12.w.4":"peintre","es-g56-u12.w.5":"scientifique (femme)","es-g56-u12.w.6":"siècle","es-g56-u12.w.7":"histoire","es-g56-u12.w.8":"voyage","es-g56-u12.w.9":"bateau","es-g56-u12.w.10":"roi","es-g56-u12.w.11":"tableau","es-g56-u12.s.0":"Hier, je suis allé au musée avec ma classe.","es-g56-u12.s.1":"Picasso a été un peintre très célèbre.","es-g56-u12.s.2":"Marie Curie a fait une découverte importante.","es-g56-u12.s.3":"Colomb a fait un long voyage en bateau.","es-g56-u12.s.4":"Mon grand-père a eu une vie heureuse.","es-g56-u12.s.5":"Où étais-tu hier ?","es-g56-u12.s.6":"Ce roi a vécu au XVe siècle.","es-g56-u12.s.7":"Nous sommes allés voir des tableaux anciens.","es-g56-u12.g.title":"Le passé irrégulier : fui, hice, tuve, estuve","es-g56-u12.g.x.0":"ir et ser ont le même passé : fui, fuiste, fue, fuimos, fueron. (je suis allé / j'ai été)","es-g56-u12.g.x.1":"hacer : hice, hiciste, hizo, hicimos, hicieron. tener : tuve, tuviste, tuvo, tuvimos, tuvieron.","es-g56-u12.g.x.2":"estar : estuve, estuviste, estuvo, estuvimos, estuvieron. Ces formes du passé n'ont pas d'accent.","es-g56-u12.g.0":"Hier, je suis allé au parc.","es-g56-u12.g.1":"Picasso a été un grand peintre.","es-g56-u12.g.2":"Qu'est-ce que tu as fait dimanche ?","es-g56-u12.g.3":"Elle a fait un gâteau.","es-g56-u12.g.4":"Nous avons eu un contrôle.","es-g56-u12.g.5":"Hier soir, j'étais à la maison.","es-g56-u12.g.5.task":"Ajoute « anoche » et mets au passé","es-g56-u12.g.6":"Ils sont allés à la plage.","es-g56-u12.g.6.task":"Mets au passé","es-g56-u12.g.7":"Ma grand-mère a eu cinq enfants.","es-g56-u12.g.7.task":"Mets au passé","es-g56-u12.r.ko":"Frida Kahlo, la peintre des couleurs","es-g56-u12.r.genre":"Biographie","es-g56-u12.r.p.0":"Frida Kahlo est née au Mexique en 1907. Petite, elle a été malade, et quelques années plus tard, elle a eu un grave accident de bus. Elle est restée au lit pendant des mois. Son père lui a donné des peintures et un miroir, et c'est comme ça que Frida a commencé à peindre.","es-g56-u12.r.p.1":"Frida a peint beaucoup d'autoportraits, avec des fleurs dans les cheveux et des couleurs très fortes. Elle a aussi peint les animaux qui vivaient dans sa maison bleue : des singes, des chiens, des perroquets. Elle est allée aux États-Unis et en France, et ses tableaux sont devenus célèbres dans le monde entier.","es-g56-u12.r.p.2":"Frida est morte en 1954, mais sa maison bleue est aujourd'hui un musée. Chaque année, des milliers de personnes y vont pour voir ses tableaux et son jardin.","es-g56-u12.r.q.4.o.0":"grave","es-g56-u12.r.q.4.o.1":"petit","es-g56-u12.r.q.4.o.2":"amusant","es-g56-u12.r.q.4.o.3":"bleu","es-g56-u13.title":"Je sais, je connais : saber et conocer","es-g56-u13.tip":"« Savoir faire quelque chose », c'est toujours saber : Sé nadar. « Connaître un lieu, une personne », c'est conocer.","es-g56-u13.w.0":"savoir (une information, faire quelque chose)","es-g56-u13.w.1":"connaître (une personne, un lieu)","es-g56-u13.w.2":"réponse","es-g56-u13.w.3":"adresse","es-g56-u13.w.4":"chemin","es-g56-u13.w.5":"langue","es-g56-u13.w.6":"voisine","es-g56-u13.w.7":"secret","es-g56-u13.w.8":"numéro","es-g56-u13.w.9":"monter (à vélo, à cheval)","es-g56-u13.w.10":"jouer (d'un instrument)","es-g56-u13.w.11":"capitale","es-g56-u13.s.0":"Je sais nager et faire du vélo.","es-g56-u13.s.1":"Tu connais la réponse ?","es-g56-u13.s.2":"Je connais ta voisine, elle est très gentille.","es-g56-u13.s.3":"Je ne connais pas encore Barcelone.","es-g56-u13.s.4":"Ma tante parle trois langues.","es-g56-u13.s.5":"Tu sais quelle est la capitale du Pérou ?","es-g56-u13.s.6":"Je ne connais pas ton numéro de téléphone.","es-g56-u13.s.7":"Je connais un secret, mais je ne le dis pas.","es-g56-u13.g.title":"saber (savoir) et conocer (connaître)","es-g56-u13.g.x.0":"Pour une information ou un savoir-faire, on utilise saber : Sé la respuesta. Sé nadar. (sé, sabes, sabe, sabemos, saben)","es-g56-u13.g.x.1":"Pour une personne ou un lieu (qu'on a déjà vu), on utilise conocer : Conozco a Lucía. Conozco Madrid. (conozco, conoces, conoce…)","es-g56-u13.g.x.2":"Devant une personne, on ajoute a : Conozco a tu hermano.","es-g56-u13.g.0":"Je connais la réponse.","es-g56-u13.g.1":"Je connais ton maître.","es-g56-u13.g.2":"Tu sais nager ?","es-g56-u13.g.3":"Elle connaît très bien Madrid.","es-g56-u13.g.4":"Nous connaissons l'adresse.","es-g56-u13.g.5":"Je connais ta voisine.","es-g56-u13.g.5.task":"Réécris avec « a tu vecina » (une personne)","es-g56-u13.g.6":"Je ne sais pas jouer de la guitare.","es-g56-u13.g.6.task":"Mets à la forme négative (no)","es-g56-u13.g.7":"Tu sais quelle est la capitale ?","es-g56-u13.g.7.task":"Transforme en question « ¿Tú…? »","es-g56-u14.title":"Ne fais pas ça ! : l'impératif négatif","es-g56-u14.tip":"Positif : habla/come. Négatif : no hables/no comas. Souviens-toi que les voyelles s'échangent.","es-g56-u14.w.0":"crier","es-g56-u14.w.1":"toucher","es-g56-u14.w.2":"courir","es-g56-u14.w.3":"oublier","es-g56-u14.w.4":"déranger","es-g56-u14.w.5":"jeter","es-g56-u14.w.6":"interdit","es-g56-u14.w.7":"règle","es-g56-u14.w.8":"couloir","es-g56-u14.w.9":"déchets","es-g56-u14.w.10":"poubelle","es-g56-u14.w.11":"panneau","es-g56-u14.s.0":"Ne crie pas dans la bibliothèque.","es-g56-u14.s.1":"Ne touche pas le tableau, s'il te plaît.","es-g56-u14.s.2":"Ne cours pas dans le couloir.","es-g56-u14.s.3":"N'oublie pas ton cartable.","es-g56-u14.s.4":"Ne dérange pas le chien quand il mange.","es-g56-u14.s.5":"Ne jette pas de déchets par terre.","es-g56-u14.s.6":"Il est interdit de manger en classe.","es-g56-u14.s.7":"Le panneau dit « Entrée interdite ».","es-g56-u14.g.title":"L'impératif négatif : No hables. No comas. No abras.","es-g56-u14.g.x.0":"« Ne fais pas… » se dit no + une forme spéciale : -es pour les verbes en -ar, -as pour les verbes en -er/-ir. No hables. No comas. No abras.","es-g56-u14.g.x.1":"Les voyelles sont à l'envers du positif : ¡Habla! ↔ No hables. ¡Come! ↔ No comas.","es-g56-u14.g.x.2":"Parfois l'orthographe change pour garder le son : tocar → No toques. jugar → No juegues.","es-g56-u14.g.0":"Ne crie pas, s'il te plaît.","es-g56-u14.g.1":"Ne mange pas en classe.","es-g56-u14.g.2":"N'ouvre pas la fenêtre.","es-g56-u14.g.3":"Ne touche pas ça.","es-g56-u14.g.4":"Ne joue pas avec le feu.","es-g56-u14.g.5":"Ne cours pas dans le couloir.","es-g56-u14.g.5.task":"Mets à l'impératif négatif (ne … pas)","es-g56-u14.g.6":"N'oublie pas le parapluie.","es-g56-u14.g.6.task":"Mets à l'impératif négatif (ne … pas)","es-g56-u14.g.7":"Ne jette pas de papiers par terre.","es-g56-u14.g.7.task":"Mets à l'impératif négatif (ne … pas)","es-g56-u15.title":"por et para","es-g56-u15.tip":"para regarde devant (le but), por regarde derrière (la cause). « Es para ti » / « Gracias por venir ».","es-g56-u15.w.0":"cadeau","es-g56-u15.w.1":"raison","es-g56-u15.w.2":"but","es-g56-u15.w.3":"fenêtre","es-g56-u15.w.4":"courrier","es-g56-u15.w.5":"après-midi","es-g56-u15.w.6":"semaine","es-g56-u15.w.7":"prix (coût)","es-g56-u15.w.8":"euro","es-g56-u15.w.9":"train","es-g56-u15.w.10":"forêt","es-g56-u15.w.11":"matin (demain)","es-g56-u15.s.0":"Ce cadeau est pour toi.","es-g56-u15.s.1":"J'étudie l'espagnol pour voyager au Mexique.","es-g56-u15.s.2":"Merci pour ton aide.","es-g56-u15.s.3":"Nous marchons à travers la forêt.","es-g56-u15.s.4":"J'ai acheté le livre pour 10 euros.","es-g56-u15.s.5":"L'après-midi, je joue au foot.","es-g56-u15.s.6":"Les devoirs sont pour lundi.","es-g56-u15.s.7":"J'envoie la lettre par la poste.","es-g56-u15.g.title":"por (cause, passage, prix) et para (but, destinataire, délai)","es-g56-u15.g.x.0":"para = « pour (quelqu'un), pour faire, pour (une date) » : Es para ti. Estudio para aprender. Es para el lunes.","es-g56-u15.g.x.1":"por = « à cause de, à travers, pour (un prix) » : Gracias por todo. Paso por el parque. Lo compré por dos euros.","es-g56-u15.g.x.2":"Les moments de la journée prennent por : por la mañana, por la tarde, por la noche.","es-g56-u15.g.0":"Ce cadeau est pour grand-mère.","es-g56-u15.g.1":"Merci pour le cadeau.","es-g56-u15.g.2":"J'étudie pour devenir médecin.","es-g56-u15.g.3":"Nous marchons le long de la plage.","es-g56-u15.g.4":"Le matin, je prends mon petit-déjeuner.","es-g56-u15.g.5":"Les devoirs sont pour demain.","es-g56-u15.g.5.task":"Corrige le por qui est faux","es-g56-u15.g.6":"Je l'ai acheté pour 5 euros.","es-g56-u15.g.6.task":"Corrige le para qui est faux","es-g56-u15.g.7":"Je voyage pour voir mes cousins.","es-g56-u15.g.7.task":"Corrige le por qui est faux","es-g56-u16.title":"D'abord, ensuite, enfin : raconter une histoire","es-g56-u16.tip":"Raconte ton histoire préférée en trois phrases avec primero, luego, finalmente.","es-g56-u16.w.0":"d'abord","es-g56-u16.w.1":"ensuite","es-g56-u16.w.2":"après","es-g56-u16.w.3":"enfin","es-g56-u16.w.4":"pendant que","es-g56-u16.w.5":"tout à coup","es-g56-u16.w.6":"renard","es-g56-u16.w.7":"corbeau","es-g56-u16.w.8":"fromage","es-g56-u16.w.9":"branche","es-g56-u16.w.10":"bec","es-g56-u16.w.11":"morale","es-g56-u16.s.0":"D'abord, le corbeau a trouvé un fromage.","es-g56-u16.s.1":"Ensuite, il s'est posé sur une haute branche.","es-g56-u16.s.2":"Tout à coup, un renard est arrivé.","es-g56-u16.s.3":"Pendant qu'il parlait, le renard regardait le fromage.","es-g56-u16.s.4":"Le corbeau a ouvert le bec pour chanter.","es-g56-u16.s.5":"Le fromage est tombé par terre.","es-g56-u16.s.6":"Enfin, le renard a mangé le fromage.","es-g56-u16.s.7":"La morale, c'est de ne pas croire tous les jolis mots.","es-g56-u16.g.title":"Les mots pour raconter : primero, luego, después, finalmente, mientras, de repente","es-g56-u16.g.x.0":"Pour dire l'ordre : primero (d'abord) → luego/después (ensuite) → finalmente (enfin).","es-g56-u16.g.x.1":"mientras veut dire « pendant que », de repente veut dire « tout à coup ». Ils rendent l'histoire vivante.","es-g56-u16.g.x.2":"Ces mots vont souvent au début de la phrase, avec une virgule : Primero, … Luego, … Finalmente, ….","es-g56-u16.g.0":"D'abord, je me lève tôt.","es-g56-u16.g.1":"Ensuite, je prends mon petit-déjeuner en famille.","es-g56-u16.g.2":"Enfin, je pars à l'école.","es-g56-u16.g.3":"Je chante pendant que je me douche.","es-g56-u16.g.4":"Tout à coup, il a commencé à pleuvoir.","es-g56-u16.g.5":"Après le dîner, je lis un conte.","es-g56-u16.g.5.task":"Réécris avec « después de » (après)","es-g56-u16.g.6":"D'abord, le renard a vu le fromage.","es-g56-u16.g.6.task":"Ajoute « Primero, » au début","es-g56-u16.g.7":"Enfin, le corbeau a perdu le fromage.","es-g56-u16.g.7.task":"Ajoute « Finalmente, » au début","es-g56-u16.r.ko":"Le renard et le corbeau","es-g56-u16.r.genre":"Fable","es-g56-u16.r.p.0":"Un matin, un corbeau a trouvé un morceau de fromage à la fenêtre d'une maison. Il l'a pris dans son bec et s'est envolé vers la plus haute branche d'un arbre. Il était très content et pensait le manger tranquillement.","es-g56-u16.r.p.1":"Tout à coup, un renard qui passait par là a vu le fromage. « Bonjour, monsieur le Corbeau », a dit le renard. « Quelles belles plumes ! Votre voix doit sûrement être la plus belle de la forêt. Voulez-vous chanter pour moi ? » Pendant qu'il parlait, le renard ne quittait pas le fromage des yeux.","es-g56-u16.r.p.2":"Tout fier, le corbeau a ouvert le bec pour chanter… et le fromage est tombé par terre. Enfin, le renard a ramassé le fromage et s'est enfui. Morale : ne crois pas tous les jolis mots qu'on te dit.","es-g56-u16.r.q.4.o.0":"fier","es-g56-u16.r.q.4.o.1":"affamé","es-g56-u16.r.q.4.o.2":"triste","es-g56-u16.r.q.4.o.3":"endormi"},i={...e,...s,...u,...a,...t};export{i as default};
